window.__PAGE_RUNTIME_PARTIALS__["partials/guia-redes-rap02-content.html"]  = "<button class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Men\u00fa\">&#9776;</button>\n<button class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\">&#9776;</button>\n\n<div class=\"layout app-layout\">\n  <nav class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-logo\">\n      <div class=\"badge\">SENA \u00b7 FPI</div>\n      <h2>Gu\u00eda 3 - Comprobar la conectividad de la red</h2>\n      <p>Sistemas Teleinform\u00e1ticos \u00b7 Redes (RAP 02)</p>\n      <button class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\">&#9664;</button>\n    </div>\n\n    <div class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\">\n      <div class=\"sf-label\">Tu grupo</div>\n      <div class=\"sf-inst\" id=\"sb-inst\"></div>\n      <div class=\"sf-meta\" id=\"sb-grupo-meta\"></div>\n      <div class=\"sf-badge\" id=\"sb-badge\"></div>\n    </div>\n    <div class=\"sidebar-noficha\" id=\"sb-ficha-warn\">\n      <a href=\"index.html\">Inicio | Seleccionar grupo / ficha</a>\n    </div>\n\n    <div class=\"progress-wrap\">\n      <div class=\"progress-label\">\n        <span>Progreso</span>\n        <span id=\"progressValue\">0%</span>\n      </div>\n      <div class=\"progress-bar-bg\">\n        <div class=\"progress-bar\" id=\"progressBar\"></div>\n      </div>\n      <p class=\"progress-note\">El avance se guarda localmente en este navegador.</p>\n      <button type=\"button\" class=\"reset-button\" id=\"resetProgress\">Reiniciar respuestas</button>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Informaci\u00f3n</div>\n      <a class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128203;</span> Identificaci\u00f3n</a>\n      <a class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128075;</span> Presentaci\u00f3n</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Actividades</div>\n      <a class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128172;</span> 3.1 Reflexi\u00f3n Inicial <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"><span class=\"icon\">&#128269;</span> 3.2 Contextualizaci\u00f3n <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128218;</span> 3.3 Apropiaci\u00f3n <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"><span class=\"icon\">&#128640;</span> 3.4 Transferencia <span class=\"check\">&#10003;</span></a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Recursos</div>\n      <a class=\"nav-link\" href=\"#quiz\" onclick=\"setActive(this)\"><span class=\"icon\">&#10067;</span> Quiz de conectividad</a>\n      <a class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"><span class=\"icon\">&#128202;</span> Evidencias</a>\n      <a class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"><span class=\"icon\">&#128214;</span> Glosario</a>\n      <a class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"><span class=\"icon\">&#128279;</span> Referencias</a>\n    </div>\n\n    <a class=\"nav-home-link\" href=\"calendario-academico-2026.html\">&#128197; <span>Calendario 2026</span></a>\n    <a class=\"nav-home-link\" href=\"index.html\">&#127968; <span>Volver al Inicio</span></a>\n  </nav>\n\n  <div class=\"main app-main\">\n    <div class=\"topbar\">\n      <div class=\"topbar-title\"><strong>Gu\u00eda 3 - Comprobar la conectividad de la red</strong></div>\n      <div class=\"topbar-meta\">\n        <span class=\"meta-item\"><span>&#9201;</span><span>112 horas</span></span>\n        <span class=\"meta-item\"><span>&#128197;</span><span>2026</span></span>\n        <span class=\"meta-item\"><span>&#127979;</span><span id=\"topbarCampus\">Santa B\u00e1rbara</span></span>\n      </div>\n    </div>\n\n    <div class=\"content\">\n      <div class=\"hero\" id=\"inicio\">\n        <div class=\"tag\">Gu\u00eda 3 | Fase: Planeaci\u00f3n \u00b7 RAP 02</div>\n        <h1>Comprobar la conectividad de la red</h1>\n        <p>\n          En la Gu\u00eda 2 aprendiste a identificar tipos de redes, topolog\u00edas, medios de transmisi\u00f3n y\n          direccionamiento IP. Ahora el contexto cambia: ya no se trata de definir c\u00f3mo es una red,\n          sino de <strong>verificar que funciona correctamente</strong>. Desarrollar\u00e1s un procedimiento\n          sistem\u00e1tico de diagn\u00f3stico y comprobaci\u00f3n de conectividad usando las herramientas y comandos\n          correctos, aplicado a MiPymes reales de Boyac\u00e1.\n        </p>\n        <div class=\"hero-meta\">\n          <div class=\"hero-meta-item\">&#127963; SENA &mdash; Servicio Nacional de Aprendizaje</div>\n          <div class=\"hero-meta-item\">&#128205; Comprobar la conectividad de la red</div>\n          <div class=\"hero-meta-item\">&#9201; 112 horas</div>\n          <div class=\"hero-meta-item\">&#127891; C\u00f3digo: 233108 \u00b7 V1</div>\n        </div>\n      </div>\n\n      <div id=\"identificacion\" class=\"section-title\">Identificaci\u00f3n de la Gu\u00eda</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8f5e9\">&#128203;</div>\n            <div><h3>Datos del Programa de Formaci\u00f3n</h3><p>Informaci\u00f3n oficial del programa y la competencia</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <div class=\"table-scroll\">\n            <table class=\"data-table ident-table\">\n              <tbody>\n                <tr><td>Denominaci\u00f3n del Programa</td><td>T\u00e9cnico en Sistemas Teleinform\u00e1ticos</td></tr>\n                <tr><td>C\u00f3digo del Programa</td><td>233108 \u00b7 V1</td></tr>\n                <tr><td>Nombre del Proyecto Formativo</td><td>Alfabetizaci\u00f3n digital, asesor\u00eda t\u00e9cnica y ciberseguridad para la mejora de actividades productivas locales en la zona de influencia del CIAS.</td></tr>\n                <tr><td>Fase del Proyecto</td><td>Planeaci\u00f3n</td></tr>\n                <tr><td>Actividad del Proyecto</td><td>Implementar procesos de soporte t\u00e9cnico b\u00e1sico, personalizaci\u00f3n de herramientas digitales y orientaci\u00f3n en ciberseguridad.</td></tr>\n                <tr><td>Resultado de Aprendizaje</td><td>RAP 02 - Comprobar la conectividad de la red, de acuerdo con normativa de telecomunicaciones y orden de trabajo.</td></tr>\n                <tr><td>Duraci\u00f3n</td><td>112 horas</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <div id=\"presentacion\" class=\"section-title\">Presentaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e3f2fd\">&#128075;</div>\n            <div><h3>Bienvenida a la Gu\u00eda</h3><p>Del \u00absaber teor\u00eda\u00bb al \u00abdar soporte real\u00bb</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\">\n            Cordial saludo, aprendiz. En la gu\u00eda anterior aprendiste a identificar tipos de redes,\n            topolog\u00edas, medios de transmisi\u00f3n y el esquema de direccionamiento IP. Ahora verificar\u00e1s\n            que una red funciona correctamente: esa es la diferencia entre un t\u00e9cnico que sabe teor\u00eda\n            y uno que puede dar soporte real en una MiPyme de Boyac\u00e1.\n          </p>\n          <p class=\"intro-text\">\n            Imagina que la se\u00f1ora Carmen &mdash;la due\u00f1a de la papeler\u00eda&mdash; llama porque \u00abel computador\n            no puede imprimir en red\u00bb y \u00abla c\u00e1mara de seguridad no aparece\u00bb. El t\u00e9cnico no puede abrir\n            el computador ni cambiar cables al azar: necesita un <strong>m\u00e9todo</strong>. Ese m\u00e9todo es\n            precisamente lo que desarrollar\u00e1s en esta gu\u00eda.\n          </p>\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128204; Lo que necesitas para esta gu\u00eda</div>\n            <p>Equipo con Windows 10/11, acceso a CMD, conexi\u00f3n a internet y Cisco Packet Tracer\n            (Switch 2960 y Router 4321). <strong>Toma captura de pantalla de cada prueba: sin\n            evidencia, no hay evaluaci\u00f3n.</strong></p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.1 REFLEXI\u00d3N INICIAL \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"reflexion\" class=\"section-title\">3.1 Actividades de Reflexi\u00f3n Inicial</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff3e0\">&#128172;</div>\n            <div><h3>Caso: La Ferreter\u00eda Don Misael &mdash; Sogamoso, Boyac\u00e1</h3><p>1 actividad \u00b7 reflexi\u00f3n individual + plenaria</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128736; El caso</h3>\n            <p>Don Misael tiene una ferreter\u00eda con 5 computadores en red, una impresora compartida,\n            una c\u00e1mara IP de vigilancia y un punto de venta conectado al router. Un lunes en la ma\u00f1ana\n            llama desesperado: el computador de caja no puede imprimir; dos computadores no tienen\n            acceso a internet, aunque s\u00ed se ven entre ellos en la red local; la c\u00e1mara desapareci\u00f3 del\n            sistema de vigilancia; y el punto de venta procesa las transacciones, pero muy lento.</p>\n            <p>Antes de ir al local, usted como t\u00e9cnico necesita organizar su diagn\u00f3stico.</p>\n          </article>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.1.1</span>\n              <span class=\"activity-title\">Reflexi\u00f3n individual escrita</span>\n              <span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Responde con tus propias palabras. No busques\n              informaci\u00f3n: escribe lo que ya sabes o intuyes a partir de la Gu\u00eda 2.</p>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfPor qu\u00e9 crees que el computador de caja no puede imprimir si la red local funciona entre los dem\u00e1s equipos?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p1\" data-track placeholder=\"Piensa en la impresora, su IP, el cable o el servicio de impresi\u00f3n.\"></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 diferencia hay entre \u00abno tener internet\u00bb y \u00abno estar en la red\u00bb? \u00bfC\u00f3mo lo identificar\u00edas?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p2\" data-track placeholder=\"Piensa en la LAN vs. la salida a internet (gateway).\"></textarea></label>\n                <label><span>3. \u00bfPor qu\u00e9 la c\u00e1mara IP puede desaparecer del sistema aunque el cable siga conectado?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p3\" data-track placeholder=\"Piensa en la IP de la c\u00e1mara y en el servicio que asigna direcciones.\"></textarea></label>\n                <label><span>4. \u00bfQu\u00e9 har\u00edas primero al llegar al local: revisar el router, los cables o los computadores? \u00bfPor qu\u00e9 ese orden?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p4\" data-track placeholder=\"Justifica tu m\u00e9todo de diagn\u00f3stico.\"></textarea></label>\n                <label><span>5. \u00bfQu\u00e9 comandos de Windows conoces que podr\u00edan ayudarte a diagnosticar alguno de estos problemas?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p5\" data-track placeholder=\"Ej.: ipconfig, ping, tracert, nslookup...\"></textarea></label>\n                <div id=\"reflexion311DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarReflexion311\" class=\"btn-save-response\" onclick=\"actStd_save_reflexion311()\">&#128190; Guardar respuestas</button>\n                  <button type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_reflexion311()\">&#128196; Exportar a Word</button>\n                </div>\n                <div id=\"statusReflexion311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n                <div data-act-std-delivery=\"reflexion311\"></div>\n              </article>\n              <div class=\"info-box\" style=\"margin-top:14px\">\n                <div class=\"label\">&#128483; Paso 2 \u2014 Socializaci\u00f3n en plenaria</div>\n                <p>El instructor modera la conversaci\u00f3n. Cada aprendiz comparte una respuesta (2-3 minutos).\n                Se construye colectivamente en el tablero un mapa de <em>s\u00edntomas &rarr; posibles causas &rarr;\n                herramientas de diagn\u00f3stico</em>.</p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.2 CONTEXTUALIZACI\u00d3N \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"contexto\" class=\"section-title\">3.2 Contextualizaci\u00f3n e identificaci\u00f3n de conocimientos</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#ede7f6\">&#128269;</div>\n            <div><h3>Bloques A\u2013D: componentes y protocolos de red</h3><p>4 bloques de estudio + 1 entrega compilada (PDF)</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">Antes de diagnosticar fallas necesitas comprender los\n          componentes y protocolos que hacen funcionar una red. Explora cada bloque, responde y elabora el producto.</p>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.1</span><span class=\"activity-title\">Bloque A \u2014 Router, Switch y Access Point</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>Router vs Switch vs Access Point &mdash; &iquest;cu&aacute;l hace qu&eacute;?</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199770615?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 1\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>Router vs Switch vs Hub &mdash; explicaci&oacute;n visual</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=1z0ULvg_pW8\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n                <p style=\"margin-top:10px;font-size:.86rem\">Apoyo: Cisco Skills for All &mdash; Networking Basics, M&oacute;dulo 4.</p>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. En la Ferreter\u00eda Don Misael: \u00bfqu\u00e9 dispositivo conecta los 5 PC entre s\u00ed? \u00bfCu\u00e1l da salida a internet?</span><textarea rows=\"3\" data-store=\"g3r_321_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfPor qu\u00e9 el router tiene dos interfaces IP diferentes (una hacia la LAN y otra hacia internet)?</span><textarea rows=\"3\" data-store=\"g3r_321_q2\" data-track></textarea></label>\n                <label><span>3. \u00bfQu\u00e9 diferencia hay entre el puerto LAN y el puerto WAN de un router dom\u00e9stico?</span><textarea rows=\"3\" data-store=\"g3r_321_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> dibuja el diagrama de red de la ferreter\u00eda (5 PC, impresora, c\u00e1mara IP, switch y router) y etiqueta la funci\u00f3n de cada dispositivo.</p>\n                <div id=\"bloqueA321DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueA321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueA321()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueA321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.2</span><span class=\"activity-title\">Bloque B \u2014 Protocolo TCP/IP y modelo de capas</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>TCP/IP explicado visualmente &mdash; las 4 capas del modelo</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199775334?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 2\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>Modelo TCP/IP y OSI &mdash; comparaci&oacute;n y capas explicadas</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=PpsEaqJV_A0\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfQu\u00e9 hace la capa de Red del modelo TCP/IP? \u00bfQu\u00e9 protocolo opera en ella?</span><textarea rows=\"3\" data-store=\"g3r_322_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 hace la capa de Transporte? \u00bfCu\u00e1l es la diferencia entre TCP y UDP?</span><textarea rows=\"3\" data-store=\"g3r_322_q2\" data-track></textarea></label>\n                <label><span>3. Cuando un PC hace ping a otro, \u00bfen qu\u00e9 capa del modelo TCP/IP opera el protocolo ICMP?</span><textarea rows=\"3\" data-store=\"g3r_322_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> completa la tabla comparativa de las 4 capas TCP/IP: nombre, funci\u00f3n principal, protocolo principal y equivalencia con la capa OSI.</p>\n                <div id=\"bloqueB322DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueB322\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueB322()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueB322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.3</span><span class=\"activity-title\">Bloque C \u2014 Servicios de red: DHCP, DNS y Firewall</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Videos de referencia</div>\n                <div style=\"display:flex;gap:8px;margin:10px 0 12px\">\n                  <button type=\"button\" id=\"tabC323-btn-1\" onclick=\"showVideoBloque323(1)\"\n                    style=\"flex:1;padding:8px 12px;border-radius:8px;border:2px solid #2e7d32;cursor:pointer;font-size:0.85rem;font-weight:600;font-family:inherit;background:#2e7d32;color:#fff\">\n                    &#127968; DHCP\n                  </button>\n                  <button type=\"button\" id=\"tabC323-btn-2\" onclick=\"showVideoBloque323(2)\"\n                    style=\"flex:1;padding:8px 12px;border-radius:8px;border:2px solid #2e7d32;cursor:pointer;font-size:0.85rem;font-weight:600;font-family:inherit;background:#e8f5e9;color:#1b5e20\">\n                    &#127758; DNS\n                  </button>\n                </div>\n                <div id=\"videoC323-1\">\n                  <p><strong>&iquest;Qu&eacute; es DHCP y c&oacute;mo funciona?</strong></p>\n                  <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                    <iframe src=\"https://player.vimeo.com/video/1199777556?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                      style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                      allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                      referrerpolicy=\"strict-origin-when-cross-origin\"\n                      title=\"guia 3 - 3\"></iframe>\n                  </div>\n                  <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                  <a href=\"https://www.youtube.com/watch?v=e6-TaH5bkjo\" target=\"_blank\" rel=\"noopener\"\n                    style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                    &#9654; Ver en YouTube\n                  </a>\n                </div>\n                <div id=\"videoC323-2\" style=\"display:none\">\n                  <p><strong>&iquest;Qu&eacute; es DNS y para qu&eacute; sirve?</strong></p>\n                  <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                    <iframe src=\"https://player.vimeo.com/video/1199777696?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                      style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                      allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                      referrerpolicy=\"strict-origin-when-cross-origin\"\n                      title=\"guia 3 - 4\"></iframe>\n                  </div>\n                  <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                  <a href=\"https://www.youtube.com/watch?v=mpQZVYPuDGU\" target=\"_blank\" rel=\"noopener\"\n                    style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                    &#9654; Ver en YouTube\n                  </a>\n                </div>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. El router asigna IPs autom\u00e1ticamente. \u00bfQu\u00e9 servicio hace eso? \u00bfQu\u00e9 pasa si ese servicio falla?</span><textarea rows=\"3\" data-store=\"g3r_323_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfPor qu\u00e9 dos PC de la misma red pueden tener internet, pero uno no? \u00bfC\u00f3mo se relaciona con DHCP?</span><textarea rows=\"3\" data-store=\"g3r_323_q2\" data-track></textarea></label>\n                <label><span>3. \u00bfQu\u00e9 tiene que ver el DNS con que una p\u00e1gina web no cargue, aunque haya conexi\u00f3n a internet?</span><textarea rows=\"3\" data-store=\"g3r_323_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> para cada servicio (DHCP, DNS, Firewall) escribe qu\u00e9 hace, qu\u00e9 pasa cuando falla y c\u00f3mo se detecta la falla desde un PC con comandos de Windows.</p>\n                <div id=\"bloqueC323DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueC323\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueC323()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueC323\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.4</span><span class=\"activity-title\">Bloque D \u2014 IPs p\u00fablicas vs. privadas y NAT</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>IP p&uacute;blica vs IP privada &mdash; diferencia y NAT explicado</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199779968?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 5\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>NAT explicado &mdash; c&oacute;mo funciona la traducci&oacute;n de direcciones</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=po8ZFG0Xc4Q\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfPor qu\u00e9 los 5 PC de la ferreter\u00eda tienen IPs privadas, pero todos salen a internet con una sola IP p\u00fablica?</span><textarea rows=\"3\" data-store=\"g3r_324_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 es NAT y cu\u00e1l dispositivo lo realiza en una red de MiPyme?</span><textarea rows=\"3\" data-store=\"g3r_324_q2\" data-track></textarea></label>\n                <label><span>3. Si haces ping a 8.8.8.8 y funciona, pero no puedes abrir www.google.com, \u00bfcu\u00e1l servicio fall\u00f3? \u00bfPor qu\u00e9?</span><textarea rows=\"3\" data-store=\"g3r_324_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> dibuja un esquema que muestre c\u00f3mo 3 PC con IPs privadas salen a internet con una sola IP p\u00fablica. Etiqueta el rol de NAT y del router.</p>\n                <div id=\"bloqueD324DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueD324\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueD324()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueD324\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div style=\"margin:16px 0;padding:20px 22px;background:#e8f5e9;border:2px solid #2e7d32;border-radius:12px;text-align:center\">\n            <div style=\"font-size:1rem;font-weight:700;color:#1b5e20;margin-bottom:6px\">&#128196; Exportar contextualizaci\u00f3n completa</div>\n            <p style=\"margin:0 0 16px;font-size:.88rem;color:#2e4a2e\">Guarda las respuestas de los 4 bloques antes de exportar. El documento incluir&aacute; los an&aacute;lisis de los Bloques A, B, C y D.</p>\n            <button type=\"button\" onclick=\"actStd_export_exportBloques321a324()\"\n              style=\"display:inline-flex;align-items:center;gap:10px;padding:13px 28px;background:#2e7d32;color:#fff;border:none;border-radius:10px;font-size:1rem;font-weight:700;font-family:inherit;cursor:pointer;box-shadow:0 2px 8px rgba(46,125,50,.35)\">\n              &#128196; Exportar Bloques A &ndash; D a Word\n            </button>\n          </div>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.5</span><span class=\"activity-title\">Entrega \u2014 Productos de contextualizaci\u00f3n (PDF)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Compila los 4 productos (diagrama de red, tabla TCP/IP,\n              an\u00e1lisis DHCP/DNS/Firewall y esquema NAT) en un solo PDF y entr\u00e9galo a Drive.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>Contextualizacion_Conectividad_NombreAprendiz_FICHA.pdf</code></p></div>\n              <div data-act-std-delivery=\"entregaContexto325\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.3 APROPIACI\u00d3N \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"apropiacion\" class=\"section-title\">3.3 Actividades de Apropiaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e0f2f1\">&#128218;</div>\n            <div><h3>Comandos de diagn\u00f3stico y procedimiento de aver\u00edas</h3><p>2 actividades \u00b7 pr\u00e1ctica CLI + presentaci\u00f3n t\u00e9cnica</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.3.1</span><span class=\"activity-title\">Comandos de diagn\u00f3stico CLI \u2014 exploraci\u00f3n y pr\u00e1ctica</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Los comandos son la herramienta principal de un t&eacute;cnico de redes.\n              Ejecuta cada comando en CMD (<kbd style=\"background:#222;color:#fff;padding:2px 7px;border-radius:4px;font-size:.85em\">Windows + R</kbd> &rarr; escribe <kbd style=\"background:#222;color:#fff;padding:2px 7px;border-radius:4px;font-size:.85em\">cmd</kbd> &rarr; Enter), toma captura y registra el resultado.</p>\n\n              <div style=\"display:flex;flex-direction:column;gap:10px;margin:14px 0\">\n\n                <!-- Comando 1 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">1</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ipconfig /all</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ipconfig /all')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra IP, m&aacute;scara, gateway, DNS y MAC del equipo.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 2 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">2</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping 127.0.0.1</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping 127.0.0.1')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Loopback: verifica que la tarjeta de red del propio equipo funciona.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 3 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#fff8e1;border:1.5px solid #ffe082;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#f57f17;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">3</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping [IP del gateway]</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping ')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Verifica la comunicaci&oacute;n con el router. Si falla: problema en la LAN. <em>(reemplaza con la IP de tu gateway)</em></p>\n                  </div>\n                </div>\n\n                <!-- Comando 4 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">4</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping 8.8.8.8</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping 8.8.8.8')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Conectividad a internet por IP. Si falla pero el gateway responde: router/ISP.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 5 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">5</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping google.com</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping google.com')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Verifica DNS adem&aacute;s de internet. Si 8.8.8.8 responde pero el nombre no: falla el DNS.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 6 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">6</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">tracert 8.8.8.8</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'tracert 8.8.8.8')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra la ruta de saltos hasta el destino. &Uacute;til para localizar d&oacute;nde se corta la conexi&oacute;n.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 7 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">7</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">nslookup google.com</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'nslookup google.com')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Consulta el servidor DNS para resolver un nombre a una IP.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 8 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">8</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">netstat -n</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'netstat -n')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra las conexiones de red activas con IPs y puertos.</p>\n                  </div>\n                </div>\n\n              </div>\n              <article class=\"notes-card\">\n                <label><span>ipconfig /all \u2014 \u00bfIP por DHCP o est\u00e1tica? \u00bfgateway? \u00bfDNS primario?</span><textarea rows=\"2\" data-store=\"g3r_331_ipconfig\" data-track></textarea></label>\n                <label><span>ping 127.0.0.1 \u2014 \u00bfqu\u00e9 respuesta obtuviste?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_local\" data-track></textarea></label>\n                <label><span>ping [gateway] \u2014 \u00bfhubo respuesta? \u00bftiempo (ms)?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_gw\" data-track></textarea></label>\n                <label><span>ping 8.8.8.8 \u2014 \u00bfhubo respuesta? \u00bfconclusi\u00f3n sobre tu internet?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_8888\" data-track></textarea></label>\n                <label><span>ping google.com \u2014 \u00bfhubo respuesta? compara con el anterior.</span><textarea rows=\"2\" data-store=\"g3r_331_ping_google\" data-track></textarea></label>\n                <label><span>tracert 8.8.8.8 \u2014 \u00bfcu\u00e1ntos saltos? \u00bfprimer salto y su IP?</span><textarea rows=\"2\" data-store=\"g3r_331_tracert\" data-track></textarea></label>\n                <label><span>nslookup google.com \u2014 \u00bfqu\u00e9 IP devolvi\u00f3? \u00bfqu\u00e9 servidor DNS respondi\u00f3?</span><textarea rows=\"2\" data-store=\"g3r_331_nslookup\" data-track></textarea></label>\n                <label><span>netstat -n \u2014 identifica 2 conexiones activas (IP remota y puerto).</span><textarea rows=\"2\" data-store=\"g3r_331_netstat\" data-track></textarea></label>\n                <div id=\"comandos331DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarComandos331\" class=\"btn-save-response\" onclick=\"actStd_save_comandos331()\">&#128190; Guardar respuestas</button>\n                  <button type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_comandos331()\">&#128196; Exportar a Word</button>\n                </div>\n                <div id=\"statusComandos331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.3.2</span><span class=\"activity-title\">Procedimiento de diagn\u00f3stico de aver\u00edas \u2014 presentaci\u00f3n t\u00e9cnica</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Un t\u00e9cnico profesional no prueba comandos al azar: sigue un m\u00e9todo.\n              Elabora una presentaci\u00f3n (PowerPoint, Canva o Google Slides, <strong>m\u00ednimo 15 diapositivas</strong>) aplicando el procedimiento estructurado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#128221; Procedimiento de resoluci\u00f3n de aver\u00edas</div>\n                <p>1) Identificar el problema \u00b7 2) Establecer teor\u00eda de causa probable \u00b7 3) Comprobar la teor\u00eda \u00b7\n                4) Establecer plan de acci\u00f3n \u00b7 5) Implementar la soluci\u00f3n (o escalar) \u00b7 6) Verificar el funcionamiento completo \u00b7 7) Documentar.</p>\n              </div>\n              <div class=\"table-scroll\">\n                <table class=\"data-table\">\n                  <thead><tr><th>#</th><th>Escenario de falla</th><th>Contexto en MiPyme</th></tr></thead>\n                  <tbody>\n                    <tr><td>1</td><td>Indicadores luminosos</td><td>El switch tiene un puerto con luz \u00e1mbar en vez de verde. \u00bfQu\u00e9 indica cada color?</td></tr>\n                    <tr><td>2</td><td>Errores de hardware/software</td><td>Un PC no aparece en la red aunque el cable est\u00e1 conectado. Secuencia ping 127.0.0.1 &rarr; gateway.</td></tr>\n                    <tr><td>3</td><td>Problemas de cableado</td><td>Dos PC se ven en LAN pero sin internet. \u00bfCable, switch o router?</td></tr>\n                    <tr><td>4</td><td>Conexiones inal\u00e1mbricas</td><td>Wi-Fi conectado pero no abre p\u00e1ginas. Distinguir falla de DNS vs. internet.</td></tr>\n                    <tr><td>5</td><td>Servicios de red</td><td>DHCP no asigna IPs y todos muestran 169.254.x.x. \u00bfQu\u00e9 significa? \u00bfSoluci\u00f3n temporal?</td></tr>\n                  </tbody>\n                </table>\n              </div>\n              <p class=\"intro-text\" style=\"font-size:.86rem\">Para cada escenario indica: s\u00edntoma observable, causa probable, comandos a usar, c\u00f3mo interpretas el resultado y acci\u00f3n correctiva.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>PresentacionAverias_NombreAprendiz_FICHA</code></p></div>\n              <div data-act-std-delivery=\"presentacion332\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.4 TRANSFERENCIA \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"transferencia\" class=\"section-title\">3.4 Transferencia del Conocimiento</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8eaf6\">&#128640;</div>\n            <div><h3>Laboratorio en Cisco Packet Tracer</h3><p>Red de edificio de dos plantas \u00b7 configurar y comprobar conectividad</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128421; Escenario \u2014 OccidenteServicios Ltda., Puerto Boyac&aacute;</h3>\n            <p>Edificio de 2 pisos. <strong>Planta 1</strong>: &aacute;rea de administraci&oacute;n \u2014 red <code>192.168.1.0/24</code>,\n            Switch S1 y <strong>4 PCs</strong> (contabilidad, gerencia, recepci&oacute;n y soporte). <strong>Planta 2</strong>:\n            &aacute;rea de operaciones \u2014 red <code>192.168.2.0/24</code>, Switch S2 y <strong>4 PCs</strong> (bodega, despacho,\n            calidad y sistemas). Un router R1 interconecta ambas plantas.\n            <strong>El objetivo no es solo configurar: es comprobar que la red funciona</strong> usando las herramientas de\n            diagn&oacute;stico. Herramientas: 2 &times; Switch 2960 (12 puertos), Router 4321.</p>\n          </article>\n\n          <div class=\"table-scroll\" style=\"margin-top:14px\">\n            <table class=\"data-table\">\n              <thead><tr><th>Dispositivo</th><th>Interfaz</th><th>Direcci&oacute;n IP</th><th>M&aacute;scara</th><th>Gateway</th><th>&Aacute;rea</th></tr></thead>\n              <tbody>\n                <tr><td><strong>R1</strong></td><td>Gi0/0/0</td><td>192.168.1.1</td><td>255.255.255.0</td><td>\u2014</td><td>Router \u2014 enlace Planta 1</td></tr>\n                <tr><td><strong>R1</strong></td><td>Gi0/0/1</td><td>192.168.2.1</td><td>255.255.255.0</td><td>\u2014</td><td>Router \u2014 enlace Planta 2</td></tr>\n                <tr><td><strong>S1</strong></td><td>VLAN 1</td><td>192.168.1.2</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Switch Planta 1</td></tr>\n                <tr><td><strong>S2</strong></td><td>VLAN 1</td><td>192.168.2.2</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Switch Planta 2</td></tr>\n                <tr><td>PC0 \u2014 Contabilidad</td><td>Fa0</td><td>192.168.1.10</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC1 \u2014 Gerencia</td><td>Fa0</td><td>192.168.1.11</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC2 \u2014 Recepci&oacute;n</td><td>Fa0</td><td>192.168.1.12</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC3 \u2014 Soporte</td><td>Fa0</td><td>192.168.1.13</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC4 \u2014 Bodega</td><td>Fa0</td><td>192.168.2.10</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC5 \u2014 Despacho</td><td>Fa0</td><td>192.168.2.11</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC6 \u2014 Calidad</td><td>Fa0</td><td>192.168.2.12</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC7 \u2014 Sistemas</td><td>Fa0</td><td>192.168.2.13</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n              </tbody>\n            </table>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:14px\">\n            <div class=\"label\">&#9881; Parte 1 \u2014 Configuraci&oacute;n b&aacute;sica (requisito para las pruebas)</div>\n            <p style=\"font-size:.83rem;margin:6px 0 10px;color:#555\">Sigue cada paso en orden. No avances al siguiente hasta confirmar que el actual funciona.</p>\n            <ol style=\"margin:0;padding-left:1.3rem;display:flex;flex-direction:column;gap:10px;font-size:.88rem\">\n              <li>\n                <strong>&#128268; Construye la topolog&iacute;a en Packet Tracer</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Agrega: Router 4321 (R1), Switch 2960 (S1), Switch 2960 (S2), 4 PCs en Planta 1, 4 PCs en Planta 2.</li>\n                  <li>Conecta cada PC a su switch con <strong>cable recto</strong>.</li>\n                  <li>Conecta S1 \u2192 R1 <code>Gi0/0/0</code> y S2 \u2192 R1 <code>Gi0/0/1</code> con <strong>cable Gigabit recto</strong>.</li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#9998; Aplica configuraci&oacute;n b&aacute;sica en R1, S1 y S2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Hostname: <code>R1-XXX</code> / <code>S1-XXX</code> / <code>S2-XXX</code> (XXX = \u00faltimos 3 d\u00edgitos de tu identidad).</li>\n                  <li>Banner de bienvenida (<code>banner motd</code>), <code>enable secret</code>, contrase\u00f1as de consola y VTY.</li>\n                  <li><code>service password-encryption</code>, <code>no ip domain-lookup</code>, <code>logging synchronous</code>.</li>\n                  <li>Guarda con <code>write memory</code> en cada dispositivo. <em>(Ver c\u00e1psula &#128204; si no recuerdas los comandos.)</em></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#127760; Configura las interfaces del router R1</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li><code>Gi0/0/0</code> \u2192 192.168.1.1 /24 (<code>no shutdown</code>) \u2014 gateway Planta 1.</li>\n                  <li><code>Gi0/0/1</code> \u2192 192.168.2.1 /24 (<code>no shutdown</code>) \u2014 gateway Planta 2.</li>\n                  <li>Verifica: <code>show ip interface brief</code> \u2014 ambas deben aparecer <strong>up/up</strong>. <em>(Ver c\u00e1psula &#128204;.)</em></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#128256; Configura la IP de administraci&oacute;n VLAN 1 en S1 y S2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>S1: <code>interface vlan 1</code> \u2192 192.168.1.2 /24 + <code>ip default-gateway 192.168.1.1</code></li>\n                  <li>S2: <code>interface vlan 1</code> \u2192 192.168.2.2 /24 + <code>ip default-gateway 192.168.2.1</code></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#128187; Asigna IPs est&aacute;ticas a los 8 PCs</strong> (seg&uacute;n tabla de direccionamiento de arriba)\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Planta 1 \u2014 PC0\u2013PC3: 192.168.1.10\u2013.13 | Gateway: 192.168.1.1</li>\n                  <li>Planta 2 \u2014 PC4\u2013PC7: 192.168.2.10\u2013.13 | Gateway: 192.168.2.1</li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#9989; Verificaci&oacute;n m&iacute;nima antes de pasar a la Parte 2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Desde PC0: <code>ping 192.168.1.1</code> \u2192 debe responder (gateway Planta 1).</li>\n                  <li>Desde PC4: <code>ping 192.168.2.1</code> \u2192 debe responder (gateway Planta 2).</li>\n                  <li>Si falla, revisa <code>no shutdown</code> en las interfaces y que la IP del PC tenga el gateway correcto.</li>\n                </ul>\n              </li>\n            </ol>\n          </div>\n\n          <!-- C\u00e1psulas de recordatorio 3.4.1 -->\n          <div style=\"display:flex;flex-direction:column;gap:8px;margin:14px 0\">\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 C&oacute;mo configurar hostname, banner y contrase&ntilde;as en un router o switch\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">enable\nconfigure terminal\nhostname R1-XXX\nbanner motd # Acceso restringido \u2014 solo personal autorizado #\nenable secret cisco123\nline console 0\n password cisco\n login\n logging synchronous\nline vty 0 4\n password cisco\n login\nservice password-encryption\nno ip domain-lookup\nend\nwrite memory</pre>\n              </div>\n            </details>\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 C&oacute;mo configurar las interfaces del router (R1) e IP de VLAN en el switch\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <p style=\"font-size:.82rem;margin:0 0 8px;font-weight:600\">Router R1 \u2014 interfaces hacia cada planta:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">interface GigabitEthernet0/0/0\n ip address 192.168.1.1 255.255.255.0\n no shutdown\ninterface GigabitEthernet0/0/1\n ip address 192.168.2.1 255.255.255.0\n no shutdown</pre>\n                <p style=\"font-size:.82rem;margin:10px 0 8px;font-weight:600\">Switch S1 \u2014 IP de administraci&oacute;n VLAN 1:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">interface vlan 1\n ip address 192.168.1.2 255.255.255.0\n no shutdown\nip default-gateway 192.168.1.1</pre>\n              </div>\n            </details>\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 Comandos de verificaci&oacute;n m&aacute;s usados\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">show ip interface brief        ! estado up/up de cada interfaz\nshow running-config            ! ver toda la configuraci\u00f3n actual\nshow ip route                  ! tabla de enrutamiento del router\nping 192.168.1.1               ! prueba de conectividad b\u00e1sica\ntracert 192.168.2.10           ! ruta de saltos (desde PC en CMD)\ntelnet 192.168.1.1             ! acceso remoto al router</pre>\n              </div>\n            </details>\n\n          </div>\n\n          <div class=\"info-box green\" style=\"margin-top:14px\"><div class=\"label\">&#9989; Parte 2 \u2014 Comprobaci&oacute;n de conectividad (captura cada prueba)</div></div>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>#</th><th>Prueba</th><th>&iquest;Qu&eacute; confirma?</th></tr></thead>\n              <tbody>\n                <tr><td>1</td><td>PC0: <code>ping 192.168.1.1</code></td><td>LAN Planta 1 \u2014 PC0 alcanza el router</td></tr>\n                <tr><td>2</td><td>PC2: <code>ping 192.168.1.13</code></td><td>Comunicaci&oacute;n entre todos los PCs de Planta 1</td></tr>\n                <tr><td>3</td><td>PC4: <code>ping 192.168.2.1</code></td><td>LAN Planta 2 \u2014 PC4 alcanza el router</td></tr>\n                <tr><td>4</td><td>PC6: <code>ping 192.168.2.13</code></td><td>Comunicaci&oacute;n entre todos los PCs de Planta 2</td></tr>\n                <tr><td>5</td><td>PC0: <code>ping 192.168.2.10</code></td><td>Enrutamiento entre plantas (Planta 1 \u2192 Planta 2)</td></tr>\n                <tr><td>6</td><td>PC7: <code>ping 192.168.1.11</code></td><td>Enrutamiento inverso (Planta 2 \u2192 Planta 1)</td></tr>\n                <tr><td>7</td><td>PC3: <code>ping 192.168.1.2</code> (S1)</td><td>Gesti&oacute;n del switch S1 accesible</td></tr>\n                <tr><td>8</td><td>PC5: <code>ping 192.168.2.2</code> (S2)</td><td>Gesti&oacute;n del switch S2 accesible</td></tr>\n                <tr><td>9</td><td>PC0: <code>tracert 192.168.2.13</code></td><td>Ruta de enrutamiento entre plantas (2 saltos)</td></tr>\n                <tr><td>10</td><td>PC4: <code>telnet 192.168.1.1</code></td><td>Acceso administrativo remoto al router desde Planta 2</td></tr>\n              </tbody>\n            </table>\n          </div>\n\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.4.1</span><span class=\"activity-title\">Entrega del laboratorio (.pkt + PDF con 10 pruebas)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Criterio clave:</strong> no basta con capturar las pruebas\n              &mdash; explica brevemente qu\u00e9 confirma cada una y qu\u00e9 habr\u00eda significado si hubiera fallado.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>Lab_Conectividad_NombreAprendiz_FICHA.pkt</code> + PDF con las 10 capturas comentadas.</p></div>\n              <div data-act-std-delivery=\"laboratorio341\"></div>\n            </div>\n          </div>\n          <!-- Actividad 3.4.2 -->\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.4.2</span>\n              <span class=\"activity-title\">Laboratorio integral \u2014 Red con DHCP, DNS, AP y NAT (Packet Tracer)</span>\n              <span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n\n              <article class=\"story-card\">\n                <h3>&#127981; Escenario \u2014 Cooperativa Agropecuaria Los Andes, Duitama</h3>\n                <p>La cooperativa tiene una sola planta con <strong>oficinas administrativas</strong> (5 PCs con IP fija) y\n                una <strong>sala de atenci&oacute;n al p&uacute;blico</strong> con Wi-Fi (3 laptops de visitantes por DHCP).\n                Adem&aacute;s requieren un servidor DNS interno, salida a internet mediante NAT y que el t&eacute;cnico\n                pueda administrar el router y el switch de forma remota. T&uacute; eres el t&eacute;cnico encargado\n                de construir y verificar toda esta red en Cisco Packet Tracer.</p>\n              </article>\n\n              <div class=\"table-scroll\" style=\"margin-top:14px\">\n                <table class=\"data-table\">\n                  <thead><tr><th>Dispositivo</th><th>Interfaz</th><th>Direcci&oacute;n IP</th><th>M&aacute;scara</th><th>Gateway</th><th>Rol</th></tr></thead>\n                  <tbody>\n                    <tr><td><strong>R1</strong></td><td>Gi0/0/0 (LAN)</td><td>192.168.20.1</td><td>255.255.255.0</td><td>\u2014</td><td>Gateway + DHCP + NAT</td></tr>\n                    <tr><td><strong>R1</strong></td><td>Gi0/0/1 (WAN)</td><td>200.15.10.1</td><td>255.255.255.252</td><td>\u2014</td><td>Salida a internet (IP p&uacute;blica)</td></tr>\n                    <tr><td><strong>ISP</strong></td><td>Gi0/0/0</td><td>200.15.10.2</td><td>255.255.255.252</td><td>\u2014</td><td>Simula el ISP</td></tr>\n                    <tr><td><strong>S1</strong></td><td>VLAN 1</td><td>192.168.20.2</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Switch de acceso (administrable)</td></tr>\n                    <tr><td><strong>DNS-Server</strong></td><td>Fa0</td><td>192.168.20.3</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Servidor DNS interno</td></tr>\n                    <tr><td>PC-Gerencia</td><td>Fa0</td><td>192.168.20.10</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Contabilidad</td><td>Fa0</td><td>192.168.20.11</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Sistemas</td><td>Fa0</td><td>192.168.20.12</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Recepci&oacute;n</td><td>Fa0</td><td>192.168.20.13</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Almac&eacute;n</td><td>Fa0</td><td>192.168.20.14</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td><strong>AP-Sala</strong></td><td>\u2014</td><td>192.168.20.5</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Access Point (SSID: CoopAndes)</td></tr>\n                    <tr><td>Laptop-Visita1</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                    <tr><td>Laptop-Visita2</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                    <tr><td>Laptop-Visita3</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                  </tbody>\n                </table>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:14px\">\n                <div class=\"label\">&#9881; Parte 1 \u2014 Construir la topolog&iacute;a y configuraci&oacute;n base</div>\n                <p style=\"font-size:.83rem;margin:6px 0 10px;color:#555\">Sigue cada paso en orden. No avances al siguiente hasta confirmar que el actual funciona.</p>\n                <ol style=\"margin:0;padding-left:1.3rem;display:flex;flex-direction:column;gap:10px;font-size:.88rem\">\n                  <li>\n                    <strong>&#128268; Construye la topolog&iacute;a en Packet Tracer</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>Dispositivos: Router 4321 (R1), Router gen\u00e9rico (ISP), Switch 2960 (S1), Access Point WRT300N (AP-Sala), 5 PCs, 1 Server, 3 Laptops.</li>\n                      <li>Conecta PCs, Server y AP \u2192 S1 con <strong>cable recto</strong>.</li>\n                      <li>Conecta S1 \u2192 R1 <code>Gi0/0/0</code> con <strong>cable recto Gigabit</strong>.</li>\n                      <li>Conecta R1 <code>Gi0/0/1</code> \u2192 ISP con <strong>cable cruzado</strong> (o Serial si el modelo lo exige).</li>\n                      <li>Las 3 Laptops se conectan <strong>por Wi-Fi</strong> al AP (SSID: <code>CoopAndes</code>). <em>(Ver c\u00e1psula &#128204; AP.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#9998; Aplica configuraci&oacute;n b&aacute;sica en R1 y S1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>Hostname: <code>R1-CoopAndes</code> / <code>S1-CoopAndes</code>.</li>\n                      <li>Banner de bienvenida, <code>enable secret</code>, contrase\u00f1as de consola y VTY.</li>\n                      <li><code>service password-encryption</code>, <code>no ip domain-lookup</code>, <code>logging synchronous</code>.</li>\n                      <li>Guarda con <code>write memory</code>. <em>(Ver c\u00e1psula &#128204; hostname/contrase\u00f1as.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#127760; Configura las interfaces de R1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li><code>Gi0/0/0</code> (LAN) \u2192 192.168.20.1 /24 + <code>no shutdown</code>.</li>\n                      <li><code>Gi0/0/1</code> (WAN) \u2192 200.15.10.1 /30 + <code>no shutdown</code>.</li>\n                      <li>ISP: <code>Gi0/0/0</code> \u2192 200.15.10.2 /30 + <code>no shutdown</code>.</li>\n                      <li>Verifica: <code>show ip interface brief</code> \u2014 todas <strong>up/up</strong>.</li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#128256; Configura VLAN 1 de administraci&oacute;n en S1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li><code>interface vlan 1</code> \u2192 192.168.20.2 /24 + <code>no shutdown</code>.</li>\n                      <li><code>ip default-gateway 192.168.20.1</code></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#128187; Asigna IPs est&aacute;ticas a los 5 PCs de oficina y al Servidor DNS</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>PC-Gerencia .10 \u00b7 PC-Contabilidad .11 \u00b7 PC-Sistemas .12 \u00b7 PC-Recepci\u00f3n .13 \u00b7 PC-Almac\u00e9n .14 \u2014 todas con gateway 192.168.20.1</li>\n                      <li>DNS-Server: 192.168.20.3 /24 | Gateway: 192.168.20.1 | DNS: 192.168.20.3</li>\n                      <li>AP-Sala: 192.168.20.5 /24 | Gateway: 192.168.20.1 <em>(ver c\u00e1psula &#128204; AP.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#9989; Verificaci&oacute;n m&iacute;nima antes de pasar a la Parte 2</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>PC-Gerencia: <code>ping 192.168.20.1</code> \u2192 debe responder.</li>\n                      <li>PC-Gerencia: <code>ping 200.15.10.2</code> (ISP WAN) \u2192 debe responder.</li>\n                      <li>Si falla, revisa <code>no shutdown</code> en <code>Gi0/0/0</code> y la IP del PC.</li>\n                    </ul>\n                  </li>\n                </ol>\n              </div>\n\n              <!-- C\u00e1psulas de recordatorio 3.4.2 -->\n              <div style=\"display:flex;flex-direction:column;gap:8px;margin:14px 0\">\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar hostname, banner y contrase&ntilde;as en R1\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">enable\nconfigure terminal\nhostname R1-CoopAndes\nbanner motd # Acceso restringido \u2014 Cooperativa Los Andes #\nenable secret cisco123\nline console 0\n password cisco\n login\n logging synchronous\nline vty 0 4\n password cisco\n login\nservice password-encryption\nno ip domain-lookup\nend\nwrite memory</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar DHCP en el router (Bloque C)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">ip dhcp excluded-address 192.168.20.1 192.168.20.99\nip dhcp pool VISITANTES\n network 192.168.20.0 255.255.255.0\n default-router 192.168.20.1\n dns-server 192.168.20.3\n!\n! Verificar asignaciones:\nshow ip dhcp binding\nshow ip dhcp pool</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar NAT overload (PAT) en el router (Bloque D)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">! 1. Definir qu\u00e9 IPs se van a traducir\naccess-list 1 permit 192.168.20.0 0.0.0.255\n!\n! 2. Aplicar NAT overload usando la interfaz WAN\nip nat inside source list 1 interface GigabitEthernet0/0/1 overload\n!\n! 3. Marcar las interfaces\ninterface GigabitEthernet0/0/0\n ip nat inside\ninterface GigabitEthernet0/0/1\n ip nat outside\n!\n! Verificar:\nshow ip nat translations\nshow ip nat statistics</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar el servidor DNS en Packet Tracer (Bloque C)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <ol style=\"font-size:.85rem;line-height:1.9;margin:0;padding-left:18px\">\n                      <li>Haz clic en el <strong>DNS-Server</strong> \u2192 pesta&ntilde;a <strong>Services</strong> \u2192 <strong>DNS</strong></li>\n                      <li>Activa el servicio: <strong>DNS Service \u2192 ON</strong></li>\n                      <li>Agrega el primer registro: Name <code>cooperativa.local</code> \u2192 Type <code>A Record</code> \u2192 Address <code>192.168.20.10</code> \u2192 <strong>Add</strong></li>\n                      <li>Agrega el segundo: Name <code>intranet.local</code> \u2192 Type <code>A Record</code> \u2192 Address <code>192.168.20.11</code> \u2192 <strong>Add</strong></li>\n                      <li>Verifica desde PC-Gerencia con <code>nslookup cooperativa.local</code> en el Command Prompt</li>\n                    </ol>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar el Access Point y conectar laptops por Wi-Fi (Bloque A)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <ol style=\"font-size:.85rem;line-height:1.9;margin:0;padding-left:18px\">\n                      <li>Haz clic en el <strong>AP-Sala</strong> \u2192 pesta&ntilde;a <strong>Config</strong> \u2192 <strong>Port 1 (Wireless)</strong></li>\n                      <li>SSID: <code>CoopAndes</code> \u2014 Authentication: <strong>WPA2-PSK</strong> \u2014 PSK Pass Phrase: <code>coop2025</code></li>\n                      <li>Asigna IP fija al AP: <code>192.168.20.5</code>, m&aacute;scara <code>255.255.255.0</code>, gateway <code>192.168.20.1</code></li>\n                      <li>En cada <strong>Laptop</strong>: retira la tarjeta de red cableada (si tiene) e instala la tarjeta <strong>WPC300N</strong></li>\n                      <li>Laptop \u2192 pesta&ntilde;a <strong>Desktop</strong> \u2192 <strong>PC Wireless</strong> \u2192 Connect \u2192 selecciona <code>CoopAndes</code> \u2192 ingresa la clave</li>\n                      <li>Verifica con <code>ipconfig</code> que recibi&oacute; IP en el rango <code>192.168.20.100\u2013150</code></li>\n                    </ol>\n                  </div>\n                </details>\n\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127968; Parte 2 \u2014 DHCP en el router (Bloque C)</div>\n                <p style=\"font-size:.88rem\">Configura un pool DHCP en R1 para los dispositivos inal&aacute;mbricos:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.82rem;overflow-x:auto;margin-top:8px\">ip dhcp pool VISITANTES\n network 192.168.20.0 255.255.255.0\n default-router 192.168.20.1\n dns-server 192.168.20.3\nip dhcp excluded-address 192.168.20.1 192.168.20.99</pre>\n                <p style=\"font-size:.85rem;margin-top:6px\">Verifica con <code>show ip dhcp binding</code> que la Laptop recibi&oacute; IP del rango .100\u2013.150.</p>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127758; Parte 3 \u2014 DNS interno (Bloque C)</div>\n                <p style=\"font-size:.88rem\">En el <strong>DNS-Server</strong> (192.168.20.3), activa el servicio DNS y agrega los registros:</p>\n                <div class=\"table-scroll\" style=\"margin-top:8px\">\n                  <table class=\"data-table\">\n                    <thead><tr><th>Nombre</th><th>Tipo</th><th>IP</th></tr></thead>\n                    <tbody>\n                      <tr><td><code>cooperativa.local</code></td><td>A Record</td><td>192.168.20.10</td></tr>\n                      <tr><td><code>intranet.local</code></td><td>A Record</td><td>192.168.20.11</td></tr>\n                    </tbody>\n                  </table>\n                </div>\n                <p style=\"font-size:.85rem;margin-top:8px\">Verifica desde PC-Admin1 con el comando <code>nslookup cooperativa.local</code> \u2014 debe devolver <code>192.168.20.10</code>.</p>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127757; Parte 4 \u2014 NAT overload (PAT) hacia internet (Bloque D)</div>\n                <p style=\"font-size:.88rem\">Configura NAT en R1 para que toda la LAN salga con la IP p&uacute;blica <code>200.15.10.1</code>:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.82rem;overflow-x:auto;margin-top:8px\">access-list 1 permit 192.168.20.0 0.0.0.255\nip nat inside source list 1 interface Gi0/0/1 overload\ninterface Gi0/0/0\n ip nat inside\ninterface Gi0/0/1\n ip nat outside</pre>\n                <p style=\"font-size:.85rem;margin-top:6px\">Verifica con <code>show ip nat translations</code> despu&eacute;s de hacer ping al ISP desde un PC.</p>\n              </div>\n\n              <div class=\"info-box green\" style=\"margin-top:14px\">\n                <div class=\"label\">&#9989; Parte 5 \u2014 Pruebas de conectividad (captura cada una)</div>\n              </div>\n              <div class=\"table-scroll\">\n                <table class=\"data-table\">\n                  <thead><tr><th>#</th><th>Prueba</th><th>&iquest;Qu&eacute; confirma?</th></tr></thead>\n                  <tbody>\n                    <tr><td>1</td><td>PC-Gerencia: <code>ping 192.168.20.1</code></td><td>LAN OK \u2014 PC de oficina alcanza el gateway</td></tr>\n                    <tr><td>2</td><td>PC-Gerencia: <code>ping 192.168.20.14</code></td><td>Comunicaci&oacute;n entre los 5 PCs de oficina</td></tr>\n                    <tr><td>3</td><td>PC-Sistemas: <code>ping 192.168.20.3</code></td><td>Servidor DNS interno alcanzable</td></tr>\n                    <tr><td>4</td><td>PC-Gerencia: <code>nslookup cooperativa.local</code></td><td>DNS interno resuelve el nombre \u2192 192.168.20.10 (Bloque C)</td></tr>\n                    <tr><td>5</td><td>Laptop-Visita1: <code>ipconfig</code></td><td>DHCP asign&oacute; IP en rango .100\u2013.150 (Bloque C)</td></tr>\n                    <tr><td>6</td><td>Laptop-Visita2: <code>ipconfig</code></td><td>Segunda laptop Wi-Fi tambi&eacute;n obtuvo IP por DHCP</td></tr>\n                    <tr><td>7</td><td>Laptop-Visita1: <code>ping 192.168.20.12</code></td><td>Visitante Wi-Fi se comunica con red cableada (AP OK \u2014 Bloque A)</td></tr>\n                    <tr><td>8</td><td>PC-Recepci&oacute;n: <code>ping 200.15.10.2</code></td><td>Salida WAN \u2014 NAT traduce IP privada a p&uacute;blica (Bloque D)</td></tr>\n                    <tr><td>9</td><td>PC-Almac&eacute;n: <code>tracert 200.15.10.2</code></td><td>Ruta de salida a internet verificada (Bloque B)</td></tr>\n                    <tr><td>10</td><td>R1: <code>show ip nat translations</code></td><td>Tabla NAT muestra todas las traducciones activas (Bloque D)</td></tr>\n                  </tbody>\n                </table>\n              </div>\n\n              <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n                <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n                  <span class=\"activity-num\">3.4.2</span>\n                  <span class=\"activity-title\">Entrega del laboratorio integral (.pkt + PDF con 10 pruebas)</span>\n                  <span class=\"activity-toggle\">&#9662;</span>\n                </div>\n                <div class=\"activity-body\">\n                  <p class=\"intro-text\" style=\"margin-top:0\"><strong>Criterio clave:</strong> en el PDF comenta cada captura\n                  explicando qu&eacute; servicio o concepto (DHCP, DNS, NAT, AP, TCP/IP) confirma esa prueba y\n                  qu&eacute; habr&iacute;a significado si hubiera fallado.</p>\n                  <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div>\n                    <p><code>LabIntegral_NombreAprendiz_FICHA.pkt</code> + PDF con las 10 capturas comentadas.</p>\n                  </div>\n                  <div data-act-std-delivery=\"caso342\"></div>\n                </div>\n              </div>\n\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 QUIZ \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"quiz\" class=\"section-title\">Quiz de conectividad</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff8e1\">&#10067;</div>\n            <div><h3>Autoevaluaci\u00f3n: comprobar conectividad</h3><p>Verifica tu comprensi\u00f3n de dispositivos, servicios y comandos</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">Pon a prueba lo aprendido sobre dispositivos activos, TCP/IP,\n          DHCP/DNS/Firewall, NAT y comandos de diagn\u00f3stico. El quiz registra tu intento.</p>\n          <a class=\"btn-save-response\" id=\"quizRedesActionLink\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"display:inline-flex;align-items:center;gap:8px;text-decoration:none\">&#10067; Abrir el quiz de conectividad</a>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 EVIDENCIAS \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"evidencias\" class=\"section-title\">Evidencias de Aprendizaje</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#e1f5fe\">&#128202;</div><div><h3>Productos y criterios de evaluaci\u00f3n</h3><p>Lo que se eval\u00faa en cada actividad</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Actividad</th><th>Evidencia / Producto</th><th>Instrumento</th></tr></thead>\n              <tbody>\n                <tr><td>3.2 Contextualizaci\u00f3n (Bloques A\u2013D)</td><td>PDF con diagrama de red, tabla TCP/IP, an\u00e1lisis DHCP/DNS/Firewall y esquema NAT.</td><td>Lista de chequeo IE-01</td></tr>\n                <tr><td>3.3.1 / 3.3.2 Apropiaci\u00f3n</td><td>Portafolio de comandos CLI + presentaci\u00f3n t\u00e9cnica de aver\u00edas.</td><td>Lista de chequeo IE-02</td></tr>\n                <tr><td>3.4 Transferencia</td><td>Archivo .pkt + PDF con 10 pruebas de conectividad comentadas.</td><td>Lista de chequeo IE-03</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 GLOSARIO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"glosario\" class=\"section-title\">Glosario de t\u00e9rminos</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#f3e5f5\">&#128214;</div><div><h3>Glosario</h3><p>T\u00e9rminos clave de la gu\u00eda</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <dl class=\"glossary\">\n            <dt>Router</dt><dd>Interconecta dos o m\u00e1s redes y reenv\u00eda paquetes IP; en MiPymes act\u00faa como puerta de enlace y puede hacer NAT.</dd>\n            <dt>Switch</dt><dd>Dispositivo de capa 2 que conmuta tramas Ethernet entre puertos dentro de una LAN.</dd>\n            <dt>Access Point (AP)</dt><dd>Brinda acceso inal\u00e1mbrico (Wi-Fi) a una red cableada.</dd>\n            <dt>TCP/IP</dt><dd>Conjunto de protocolos base de Internet organizado por capas; IP direcciona y encamina, TCP/UDP transportan datos.</dd>\n            <dt>DHCP</dt><dd>Asigna autom\u00e1ticamente IP, m\u00e1scara, gateway y DNS a los equipos cliente.</dd>\n            <dt>DNS</dt><dd>Traduce nombres de dominio (p. ej. www.google.com) a direcciones IP.</dd>\n            <dt>NAT</dt><dd>Traduce direcciones IP privadas a una o varias p\u00fablicas para salir a Internet desde una LAN.</dd>\n            <dt>ICMP</dt><dd>Protocolo de control y diagn\u00f3stico; el comando ping lo usa para verificar conectividad.</dd>\n            <dt>Gateway (Puerta de enlace)</dt><dd>IP del router por donde un equipo env\u00eda el tr\u00e1fico hacia otras redes.</dd>\n            <dt>M\u00e1scara de subred</dt><dd>Define qu\u00e9 parte de la IP es red y qu\u00e9 parte es host.</dd>\n            <dt>APIPA (169.254.x.x)</dt><dd>IP link-local autom\u00e1tica cuando el equipo no obtiene configuraci\u00f3n v\u00e1lida de DHCP.</dd>\n            <dt>VLAN</dt><dd>Segmentaci\u00f3n l\u00f3gica de una LAN en dominios de broadcast independientes.</dd>\n            <dt>tracert / traceroute</dt><dd>Muestra la ruta (saltos) hasta un destino; \u00fatil para ubicar d\u00f3nde se pierde la conexi\u00f3n.</dd>\n            <dt>nslookup</dt><dd>Consulta servidores DNS para verificar la resoluci\u00f3n de nombres.</dd>\n            <dt>netstat</dt><dd>Muestra conexiones de red activas, puertos en escucha y estad\u00edsticas.</dd>\n            <dt>Cisco Packet Tracer</dt><dd>Simulador de redes para construir topolog\u00edas, configurar dispositivos y validar conectividad.</dd>\n            <dt>Telnet</dt><dd>Acceso remoto por texto plano (sin cifrado); \u00fatil en laboratorio, no recomendado en producci\u00f3n.</dd>\n            <dt>Firewall</dt><dd>Filtra el tr\u00e1fico de red seg\u00fan reglas para permitir o bloquear comunicaciones.</dd>\n          </dl>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 REFERENCIAS \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"referencias\" class=\"section-title\">Referentes bibliogr\u00e1ficos</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#eceff1\">&#128279;</div><div><h3>Referencias (IEEE)</h3><p>Fuentes consultadas</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <ol class=\"references\">\n            <li>Cisco Networking Academy, \u00abNetworking Basics\u00bb, Cisco Skills for All.</li>\n            <li>J. Postel, \u00abInternet Protocol\u00bb, RFC 791, 1981.</li>\n            <li>J. Postel, \u00abTransmission Control Protocol\u00bb, RFC 793, 1981.</li>\n            <li>J. Postel, \u00abUser Datagram Protocol\u00bb, RFC 768, 1980.</li>\n            <li>R. Droms, \u00abDynamic Host Configuration Protocol\u00bb, RFC 2131, 1997.</li>\n            <li>P. Mockapetris, \u00abDomain names - concepts and facilities\u00bb, RFC 1034, 1987.</li>\n            <li>T. Hain, \u00abTraditional IP Network Address Translator (NAT)\u00bb, RFC 3022, 2001.</li>\n            <li>Microsoft, \u00abipconfig / ping / tracert / nslookup / netstat\u00bb, Microsoft Learn (Windows Commands).</li>\n            <li>S. Cheshire et al., \u00abDynamic Configuration of IPv4 Link-Local Addresses\u00bb, RFC 3927, 2005.</li>\n            <li>J. Postel, \u00abInternet Control Message Protocol\u00bb, RFC 792, 1981.</li>\n            <li>Cisco, \u00abVLAN Fundamentals\u00bb y \u00abCisco Packet Tracer\u00bb, netacad.com.</li>\n            <li>K. Scarfone y P. Hoffman, \u00abGuidelines on Firewalls and Firewall Policy\u00bb, NIST SP 800-41 Rev. 1, 2009.</li>\n            <li>J. Postel y J. Reynolds, \u00abTELNET Protocol Specification\u00bb, RFC 854, 1983.</li>\n          </ol>\n          <p class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\">Gu\u00eda original: Boris Vesga Cardozo (Instructor, CIAS). Actualizaci\u00f3n al Proyecto Formativo: Dubier Orlando Mill\u00e1n Barbosa (Instructor T\u00e9cnico, CIAS \u2014 Regional Boyac\u00e1).</p>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n";
window.__GUIDE_RUNTIME_PARTIALS__["partials/guia-redes-rap02-content.html"] = "<button class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Men\u00fa\">&#9776;</button>\n<button class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\">&#9776;</button>\n\n<div class=\"layout app-layout\">\n  <nav class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-logo\">\n      <div class=\"badge\">SENA \u00b7 FPI</div>\n      <h2>Gu\u00eda 3 - Comprobar la conectividad de la red</h2>\n      <p>Sistemas Teleinform\u00e1ticos \u00b7 Redes (RAP 02)</p>\n      <button class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\">&#9664;</button>\n    </div>\n\n    <div class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\">\n      <div class=\"sf-label\">Tu grupo</div>\n      <div class=\"sf-inst\" id=\"sb-inst\"></div>\n      <div class=\"sf-meta\" id=\"sb-grupo-meta\"></div>\n      <div class=\"sf-badge\" id=\"sb-badge\"></div>\n    </div>\n    <div class=\"sidebar-noficha\" id=\"sb-ficha-warn\">\n      <a href=\"index.html\">Inicio | Seleccionar grupo / ficha</a>\n    </div>\n\n    <div class=\"progress-wrap\">\n      <div class=\"progress-label\">\n        <span>Progreso</span>\n        <span id=\"progressValue\">0%</span>\n      </div>\n      <div class=\"progress-bar-bg\">\n        <div class=\"progress-bar\" id=\"progressBar\"></div>\n      </div>\n      <p class=\"progress-note\">El avance se guarda localmente en este navegador.</p>\n      <button type=\"button\" class=\"reset-button\" id=\"resetProgress\">Reiniciar respuestas</button>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Informaci\u00f3n</div>\n      <a class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128203;</span> Identificaci\u00f3n</a>\n      <a class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128075;</span> Presentaci\u00f3n</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Actividades</div>\n      <a class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128172;</span> 3.1 Reflexi\u00f3n Inicial <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"><span class=\"icon\">&#128269;</span> 3.2 Contextualizaci\u00f3n <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128218;</span> 3.3 Apropiaci\u00f3n <span class=\"check\">&#10003;</span></a>\n      <a class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"><span class=\"icon\">&#128640;</span> 3.4 Transferencia <span class=\"check\">&#10003;</span></a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Recursos</div>\n      <a class=\"nav-link\" href=\"#quiz\" onclick=\"setActive(this)\"><span class=\"icon\">&#10067;</span> Quiz de conectividad</a>\n      <a class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"><span class=\"icon\">&#128202;</span> Evidencias</a>\n      <a class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"><span class=\"icon\">&#128214;</span> Glosario</a>\n      <a class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"><span class=\"icon\">&#128279;</span> Referencias</a>\n    </div>\n\n    <a class=\"nav-home-link\" href=\"calendario-academico-2026.html\">&#128197; <span>Calendario 2026</span></a>\n    <a class=\"nav-home-link\" href=\"index.html\">&#127968; <span>Volver al Inicio</span></a>\n  </nav>\n\n  <div class=\"main app-main\">\n    <div class=\"topbar\">\n      <div class=\"topbar-title\"><strong>Gu\u00eda 3 - Comprobar la conectividad de la red</strong></div>\n      <div class=\"topbar-meta\">\n        <span class=\"meta-item\"><span>&#9201;</span><span>112 horas</span></span>\n        <span class=\"meta-item\"><span>&#128197;</span><span>2026</span></span>\n        <span class=\"meta-item\"><span>&#127979;</span><span id=\"topbarCampus\">Santa B\u00e1rbara</span></span>\n      </div>\n    </div>\n\n    <div class=\"content\">\n      <div class=\"hero\" id=\"inicio\">\n        <div class=\"tag\">Gu\u00eda 3 | Fase: Planeaci\u00f3n \u00b7 RAP 02</div>\n        <h1>Comprobar la conectividad de la red</h1>\n        <p>\n          En la Gu\u00eda 2 aprendiste a identificar tipos de redes, topolog\u00edas, medios de transmisi\u00f3n y\n          direccionamiento IP. Ahora el contexto cambia: ya no se trata de definir c\u00f3mo es una red,\n          sino de <strong>verificar que funciona correctamente</strong>. Desarrollar\u00e1s un procedimiento\n          sistem\u00e1tico de diagn\u00f3stico y comprobaci\u00f3n de conectividad usando las herramientas y comandos\n          correctos, aplicado a MiPymes reales de Boyac\u00e1.\n        </p>\n        <div class=\"hero-meta\">\n          <div class=\"hero-meta-item\">&#127963; SENA &mdash; Servicio Nacional de Aprendizaje</div>\n          <div class=\"hero-meta-item\">&#128205; Comprobar la conectividad de la red</div>\n          <div class=\"hero-meta-item\">&#9201; 112 horas</div>\n          <div class=\"hero-meta-item\">&#127891; C\u00f3digo: 233108 \u00b7 V1</div>\n        </div>\n      </div>\n\n      <div id=\"identificacion\" class=\"section-title\">Identificaci\u00f3n de la Gu\u00eda</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8f5e9\">&#128203;</div>\n            <div><h3>Datos del Programa de Formaci\u00f3n</h3><p>Informaci\u00f3n oficial del programa y la competencia</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <div class=\"table-scroll\">\n            <table class=\"data-table ident-table\">\n              <tbody>\n                <tr><td>Denominaci\u00f3n del Programa</td><td>T\u00e9cnico en Sistemas Teleinform\u00e1ticos</td></tr>\n                <tr><td>C\u00f3digo del Programa</td><td>233108 \u00b7 V1</td></tr>\n                <tr><td>Nombre del Proyecto Formativo</td><td>Alfabetizaci\u00f3n digital, asesor\u00eda t\u00e9cnica y ciberseguridad para la mejora de actividades productivas locales en la zona de influencia del CIAS.</td></tr>\n                <tr><td>Fase del Proyecto</td><td>Planeaci\u00f3n</td></tr>\n                <tr><td>Actividad del Proyecto</td><td>Implementar procesos de soporte t\u00e9cnico b\u00e1sico, personalizaci\u00f3n de herramientas digitales y orientaci\u00f3n en ciberseguridad.</td></tr>\n                <tr><td>Resultado de Aprendizaje</td><td>RAP 02 - Comprobar la conectividad de la red, de acuerdo con normativa de telecomunicaciones y orden de trabajo.</td></tr>\n                <tr><td>Duraci\u00f3n</td><td>112 horas</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <div id=\"presentacion\" class=\"section-title\">Presentaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e3f2fd\">&#128075;</div>\n            <div><h3>Bienvenida a la Gu\u00eda</h3><p>Del \u00absaber teor\u00eda\u00bb al \u00abdar soporte real\u00bb</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\">\n            Cordial saludo, aprendiz. En la gu\u00eda anterior aprendiste a identificar tipos de redes,\n            topolog\u00edas, medios de transmisi\u00f3n y el esquema de direccionamiento IP. Ahora verificar\u00e1s\n            que una red funciona correctamente: esa es la diferencia entre un t\u00e9cnico que sabe teor\u00eda\n            y uno que puede dar soporte real en una MiPyme de Boyac\u00e1.\n          </p>\n          <p class=\"intro-text\">\n            Imagina que la se\u00f1ora Carmen &mdash;la due\u00f1a de la papeler\u00eda&mdash; llama porque \u00abel computador\n            no puede imprimir en red\u00bb y \u00abla c\u00e1mara de seguridad no aparece\u00bb. El t\u00e9cnico no puede abrir\n            el computador ni cambiar cables al azar: necesita un <strong>m\u00e9todo</strong>. Ese m\u00e9todo es\n            precisamente lo que desarrollar\u00e1s en esta gu\u00eda.\n          </p>\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128204; Lo que necesitas para esta gu\u00eda</div>\n            <p>Equipo con Windows 10/11, acceso a CMD, conexi\u00f3n a internet y Cisco Packet Tracer\n            (Switch 2960 y Router 4321). <strong>Toma captura de pantalla de cada prueba: sin\n            evidencia, no hay evaluaci\u00f3n.</strong></p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.1 REFLEXI\u00d3N INICIAL \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"reflexion\" class=\"section-title\">3.1 Actividades de Reflexi\u00f3n Inicial</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff3e0\">&#128172;</div>\n            <div><h3>Caso: La Ferreter\u00eda Don Misael &mdash; Sogamoso, Boyac\u00e1</h3><p>1 actividad \u00b7 reflexi\u00f3n individual + plenaria</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128736; El caso</h3>\n            <p>Don Misael tiene una ferreter\u00eda con 5 computadores en red, una impresora compartida,\n            una c\u00e1mara IP de vigilancia y un punto de venta conectado al router. Un lunes en la ma\u00f1ana\n            llama desesperado: el computador de caja no puede imprimir; dos computadores no tienen\n            acceso a internet, aunque s\u00ed se ven entre ellos en la red local; la c\u00e1mara desapareci\u00f3 del\n            sistema de vigilancia; y el punto de venta procesa las transacciones, pero muy lento.</p>\n            <p>Antes de ir al local, usted como t\u00e9cnico necesita organizar su diagn\u00f3stico.</p>\n          </article>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.1.1</span>\n              <span class=\"activity-title\">Reflexi\u00f3n individual escrita</span>\n              <span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Responde con tus propias palabras. No busques\n              informaci\u00f3n: escribe lo que ya sabes o intuyes a partir de la Gu\u00eda 2.</p>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfPor qu\u00e9 crees que el computador de caja no puede imprimir si la red local funciona entre los dem\u00e1s equipos?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p1\" data-track placeholder=\"Piensa en la impresora, su IP, el cable o el servicio de impresi\u00f3n.\"></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 diferencia hay entre \u00abno tener internet\u00bb y \u00abno estar en la red\u00bb? \u00bfC\u00f3mo lo identificar\u00edas?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p2\" data-track placeholder=\"Piensa en la LAN vs. la salida a internet (gateway).\"></textarea></label>\n                <label><span>3. \u00bfPor qu\u00e9 la c\u00e1mara IP puede desaparecer del sistema aunque el cable siga conectado?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p3\" data-track placeholder=\"Piensa en la IP de la c\u00e1mara y en el servicio que asigna direcciones.\"></textarea></label>\n                <label><span>4. \u00bfQu\u00e9 har\u00edas primero al llegar al local: revisar el router, los cables o los computadores? \u00bfPor qu\u00e9 ese orden?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p4\" data-track placeholder=\"Justifica tu m\u00e9todo de diagn\u00f3stico.\"></textarea></label>\n                <label><span>5. \u00bfQu\u00e9 comandos de Windows conoces que podr\u00edan ayudarte a diagnosticar alguno de estos problemas?</span>\n                  <textarea rows=\"4\" data-store=\"g3r_311_p5\" data-track placeholder=\"Ej.: ipconfig, ping, tracert, nslookup...\"></textarea></label>\n                <div id=\"reflexion311DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarReflexion311\" class=\"btn-save-response\" onclick=\"actStd_save_reflexion311()\">&#128190; Guardar respuestas</button>\n                  <button type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_reflexion311()\">&#128196; Exportar a Word</button>\n                </div>\n                <div id=\"statusReflexion311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n                <div data-act-std-delivery=\"reflexion311\"></div>\n              </article>\n              <div class=\"info-box\" style=\"margin-top:14px\">\n                <div class=\"label\">&#128483; Paso 2 \u2014 Socializaci\u00f3n en plenaria</div>\n                <p>El instructor modera la conversaci\u00f3n. Cada aprendiz comparte una respuesta (2-3 minutos).\n                Se construye colectivamente en el tablero un mapa de <em>s\u00edntomas &rarr; posibles causas &rarr;\n                herramientas de diagn\u00f3stico</em>.</p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.2 CONTEXTUALIZACI\u00d3N \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"contexto\" class=\"section-title\">3.2 Contextualizaci\u00f3n e identificaci\u00f3n de conocimientos</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#ede7f6\">&#128269;</div>\n            <div><h3>Bloques A\u2013D: componentes y protocolos de red</h3><p>4 bloques de estudio + 1 entrega compilada (PDF)</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">Antes de diagnosticar fallas necesitas comprender los\n          componentes y protocolos que hacen funcionar una red. Explora cada bloque, responde y elabora el producto.</p>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.1</span><span class=\"activity-title\">Bloque A \u2014 Router, Switch y Access Point</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>Router vs Switch vs Access Point &mdash; &iquest;cu&aacute;l hace qu&eacute;?</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199770615?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 1\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>Router vs Switch vs Hub &mdash; explicaci&oacute;n visual</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=1z0ULvg_pW8\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n                <p style=\"margin-top:10px;font-size:.86rem\">Apoyo: Cisco Skills for All &mdash; Networking Basics, M&oacute;dulo 4.</p>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. En la Ferreter\u00eda Don Misael: \u00bfqu\u00e9 dispositivo conecta los 5 PC entre s\u00ed? \u00bfCu\u00e1l da salida a internet?</span><textarea rows=\"3\" data-store=\"g3r_321_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfPor qu\u00e9 el router tiene dos interfaces IP diferentes (una hacia la LAN y otra hacia internet)?</span><textarea rows=\"3\" data-store=\"g3r_321_q2\" data-track></textarea></label>\n                <label><span>3. \u00bfQu\u00e9 diferencia hay entre el puerto LAN y el puerto WAN de un router dom\u00e9stico?</span><textarea rows=\"3\" data-store=\"g3r_321_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> dibuja el diagrama de red de la ferreter\u00eda (5 PC, impresora, c\u00e1mara IP, switch y router) y etiqueta la funci\u00f3n de cada dispositivo.</p>\n                <div id=\"bloqueA321DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueA321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueA321()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueA321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.2</span><span class=\"activity-title\">Bloque B \u2014 Protocolo TCP/IP y modelo de capas</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>TCP/IP explicado visualmente &mdash; las 4 capas del modelo</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199775334?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 2\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>Modelo TCP/IP y OSI &mdash; comparaci&oacute;n y capas explicadas</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=PpsEaqJV_A0\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfQu\u00e9 hace la capa de Red del modelo TCP/IP? \u00bfQu\u00e9 protocolo opera en ella?</span><textarea rows=\"3\" data-store=\"g3r_322_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 hace la capa de Transporte? \u00bfCu\u00e1l es la diferencia entre TCP y UDP?</span><textarea rows=\"3\" data-store=\"g3r_322_q2\" data-track></textarea></label>\n                <label><span>3. Cuando un PC hace ping a otro, \u00bfen qu\u00e9 capa del modelo TCP/IP opera el protocolo ICMP?</span><textarea rows=\"3\" data-store=\"g3r_322_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> completa la tabla comparativa de las 4 capas TCP/IP: nombre, funci\u00f3n principal, protocolo principal y equivalencia con la capa OSI.</p>\n                <div id=\"bloqueB322DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueB322\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueB322()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueB322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.3</span><span class=\"activity-title\">Bloque C \u2014 Servicios de red: DHCP, DNS y Firewall</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Videos de referencia</div>\n                <div style=\"display:flex;gap:8px;margin:10px 0 12px\">\n                  <button type=\"button\" id=\"tabC323-btn-1\" onclick=\"showVideoBloque323(1)\"\n                    style=\"flex:1;padding:8px 12px;border-radius:8px;border:2px solid #2e7d32;cursor:pointer;font-size:0.85rem;font-weight:600;font-family:inherit;background:#2e7d32;color:#fff\">\n                    &#127968; DHCP\n                  </button>\n                  <button type=\"button\" id=\"tabC323-btn-2\" onclick=\"showVideoBloque323(2)\"\n                    style=\"flex:1;padding:8px 12px;border-radius:8px;border:2px solid #2e7d32;cursor:pointer;font-size:0.85rem;font-weight:600;font-family:inherit;background:#e8f5e9;color:#1b5e20\">\n                    &#127758; DNS\n                  </button>\n                </div>\n                <div id=\"videoC323-1\">\n                  <p><strong>&iquest;Qu&eacute; es DHCP y c&oacute;mo funciona?</strong></p>\n                  <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                    <iframe src=\"https://player.vimeo.com/video/1199777556?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                      style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                      allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                      referrerpolicy=\"strict-origin-when-cross-origin\"\n                      title=\"guia 3 - 3\"></iframe>\n                  </div>\n                  <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                  <a href=\"https://www.youtube.com/watch?v=e6-TaH5bkjo\" target=\"_blank\" rel=\"noopener\"\n                    style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                    &#9654; Ver en YouTube\n                  </a>\n                </div>\n                <div id=\"videoC323-2\" style=\"display:none\">\n                  <p><strong>&iquest;Qu&eacute; es DNS y para qu&eacute; sirve?</strong></p>\n                  <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                    <iframe src=\"https://player.vimeo.com/video/1199777696?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                      style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                      allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                      referrerpolicy=\"strict-origin-when-cross-origin\"\n                      title=\"guia 3 - 4\"></iframe>\n                  </div>\n                  <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                  <a href=\"https://www.youtube.com/watch?v=mpQZVYPuDGU\" target=\"_blank\" rel=\"noopener\"\n                    style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                    &#9654; Ver en YouTube\n                  </a>\n                </div>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. El router asigna IPs autom\u00e1ticamente. \u00bfQu\u00e9 servicio hace eso? \u00bfQu\u00e9 pasa si ese servicio falla?</span><textarea rows=\"3\" data-store=\"g3r_323_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfPor qu\u00e9 dos PC de la misma red pueden tener internet, pero uno no? \u00bfC\u00f3mo se relaciona con DHCP?</span><textarea rows=\"3\" data-store=\"g3r_323_q2\" data-track></textarea></label>\n                <label><span>3. \u00bfQu\u00e9 tiene que ver el DNS con que una p\u00e1gina web no cargue, aunque haya conexi\u00f3n a internet?</span><textarea rows=\"3\" data-store=\"g3r_323_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> para cada servicio (DHCP, DNS, Firewall) escribe qu\u00e9 hace, qu\u00e9 pasa cuando falla y c\u00f3mo se detecta la falla desde un PC con comandos de Windows.</p>\n                <div id=\"bloqueC323DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueC323\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueC323()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueC323\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.4</span><span class=\"activity-title\">Bloque D \u2014 IPs p\u00fablicas vs. privadas y NAT</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <div class=\"info-box green\" style=\"margin-bottom:16px\">\n                <div class=\"label\">&#127909; Video de referencia</div>\n                <p><strong>IP p&uacute;blica vs IP privada &mdash; diferencia y NAT explicado</strong></p>\n                <div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin-top:8px\">\n                  <iframe src=\"https://player.vimeo.com/video/1199779968?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\"\n                    style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\"\n                    allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media\"\n                    referrerpolicy=\"strict-origin-when-cross-origin\"\n                    title=\"guia 3 - 5\"></iframe>\n                </div>\n                <div class=\"label\" style=\"margin-top:14px\">&#128250; Video complementario</div>\n                <p><strong>NAT explicado &mdash; c&oacute;mo funciona la traducci&oacute;n de direcciones</strong></p>\n                <a href=\"https://www.youtube.com/watch?v=po8ZFG0Xc4Q\" target=\"_blank\" rel=\"noopener\"\n                  style=\"display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:9px 16px;background:#ff0000;color:#fff;border-radius:8px;font-size:0.88rem;font-weight:600;text-decoration:none\">\n                  &#9654; Ver en YouTube\n                </a>\n              </div>\n              <article class=\"notes-card\">\n                <label><span>1. \u00bfPor qu\u00e9 los 5 PC de la ferreter\u00eda tienen IPs privadas, pero todos salen a internet con una sola IP p\u00fablica?</span><textarea rows=\"3\" data-store=\"g3r_324_q1\" data-track></textarea></label>\n                <label><span>2. \u00bfQu\u00e9 es NAT y cu\u00e1l dispositivo lo realiza en una red de MiPyme?</span><textarea rows=\"3\" data-store=\"g3r_324_q2\" data-track></textarea></label>\n                <label><span>3. Si haces ping a 8.8.8.8 y funciona, pero no puedes abrir www.google.com, \u00bfcu\u00e1l servicio fall\u00f3? \u00bfPor qu\u00e9?</span><textarea rows=\"3\" data-store=\"g3r_324_q3\" data-track></textarea></label>\n                <p class=\"intro-text\" style=\"font-size:.86rem\"><strong>Producto:</strong> dibuja un esquema que muestre c\u00f3mo 3 PC con IPs privadas salen a internet con una sola IP p\u00fablica. Etiqueta el rol de NAT y del router.</p>\n                <div id=\"bloqueD324DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarBloqueD324\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueD324()\">&#128190; Guardar respuestas</button>\n                </div>\n                <div id=\"statusBloqueD324\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div style=\"margin:16px 0;padding:20px 22px;background:#e8f5e9;border:2px solid #2e7d32;border-radius:12px;text-align:center\">\n            <div style=\"font-size:1rem;font-weight:700;color:#1b5e20;margin-bottom:6px\">&#128196; Exportar contextualizaci\u00f3n completa</div>\n            <p style=\"margin:0 0 16px;font-size:.88rem;color:#2e4a2e\">Guarda las respuestas de los 4 bloques antes de exportar. El documento incluir&aacute; los an&aacute;lisis de los Bloques A, B, C y D.</p>\n            <button type=\"button\" onclick=\"actStd_export_exportBloques321a324()\"\n              style=\"display:inline-flex;align-items:center;gap:10px;padding:13px 28px;background:#2e7d32;color:#fff;border:none;border-radius:10px;font-size:1rem;font-weight:700;font-family:inherit;cursor:pointer;box-shadow:0 2px 8px rgba(46,125,50,.35)\">\n              &#128196; Exportar Bloques A &ndash; D a Word\n            </button>\n          </div>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.2.5</span><span class=\"activity-title\">Entrega \u2014 Productos de contextualizaci\u00f3n (PDF)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Compila los 4 productos (diagrama de red, tabla TCP/IP,\n              an\u00e1lisis DHCP/DNS/Firewall y esquema NAT) en un solo PDF y entr\u00e9galo a Drive.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>Contextualizacion_Conectividad_NombreAprendiz_FICHA.pdf</code></p></div>\n              <div data-act-std-delivery=\"entregaContexto325\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.3 APROPIACI\u00d3N \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"apropiacion\" class=\"section-title\">3.3 Actividades de Apropiaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e0f2f1\">&#128218;</div>\n            <div><h3>Comandos de diagn\u00f3stico y procedimiento de aver\u00edas</h3><p>2 actividades \u00b7 pr\u00e1ctica CLI + presentaci\u00f3n t\u00e9cnica</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.3.1</span><span class=\"activity-title\">Comandos de diagn\u00f3stico CLI \u2014 exploraci\u00f3n y pr\u00e1ctica</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Los comandos son la herramienta principal de un t&eacute;cnico de redes.\n              Ejecuta cada comando en CMD (<kbd style=\"background:#222;color:#fff;padding:2px 7px;border-radius:4px;font-size:.85em\">Windows + R</kbd> &rarr; escribe <kbd style=\"background:#222;color:#fff;padding:2px 7px;border-radius:4px;font-size:.85em\">cmd</kbd> &rarr; Enter), toma captura y registra el resultado.</p>\n\n              <div style=\"display:flex;flex-direction:column;gap:10px;margin:14px 0\">\n\n                <!-- Comando 1 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">1</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ipconfig /all</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ipconfig /all')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra IP, m&aacute;scara, gateway, DNS y MAC del equipo.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 2 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">2</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping 127.0.0.1</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping 127.0.0.1')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Loopback: verifica que la tarjeta de red del propio equipo funciona.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 3 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#fff8e1;border:1.5px solid #ffe082;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#f57f17;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">3</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping [IP del gateway]</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping ')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Verifica la comunicaci&oacute;n con el router. Si falla: problema en la LAN. <em>(reemplaza con la IP de tu gateway)</em></p>\n                  </div>\n                </div>\n\n                <!-- Comando 4 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">4</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping 8.8.8.8</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping 8.8.8.8')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Conectividad a internet por IP. Si falla pero el gateway responde: router/ISP.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 5 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">5</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">ping google.com</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'ping google.com')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Verifica DNS adem&aacute;s de internet. Si 8.8.8.8 responde pero el nombre no: falla el DNS.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 6 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">6</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">tracert 8.8.8.8</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'tracert 8.8.8.8')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra la ruta de saltos hasta el destino. &Uacute;til para localizar d&oacute;nde se corta la conexi&oacute;n.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 7 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">7</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">nslookup google.com</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'nslookup google.com')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Consulta el servidor DNS para resolver un nombre a una IP.</p>\n                  </div>\n                </div>\n\n                <!-- Comando 8 -->\n                <div style=\"display:flex;align-items:flex-start;gap:12px;background:#f8fffe;border:1.5px solid #b2dfdb;border-radius:10px;padding:12px 14px\">\n                  <div style=\"min-width:28px;height:28px;background:#00695c;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;flex-shrink:0\">8</div>\n                  <div style=\"flex:1;min-width:0\">\n                    <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n                      <code style=\"background:#1a237e;color:#e8eaf6;padding:4px 10px;border-radius:6px;font-size:.93rem;font-weight:700;letter-spacing:.3px\">netstat -n</code>\n                      <button type=\"button\" onclick=\"copiarComando331(this,'netstat -n')\"\n                        style=\"padding:4px 10px;background:#e3f2fd;border:1.5px solid #1565c0;border-radius:6px;font-size:.78rem;font-weight:600;color:#1565c0;cursor:pointer;font-family:inherit\">\n                        &#128203; Copiar\n                      </button>\n                    </div>\n                    <p style=\"margin:5px 0 0;font-size:.85rem;color:#37474f\">Muestra las conexiones de red activas con IPs y puertos.</p>\n                  </div>\n                </div>\n\n              </div>\n              <article class=\"notes-card\">\n                <label><span>ipconfig /all \u2014 \u00bfIP por DHCP o est\u00e1tica? \u00bfgateway? \u00bfDNS primario?</span><textarea rows=\"2\" data-store=\"g3r_331_ipconfig\" data-track></textarea></label>\n                <label><span>ping 127.0.0.1 \u2014 \u00bfqu\u00e9 respuesta obtuviste?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_local\" data-track></textarea></label>\n                <label><span>ping [gateway] \u2014 \u00bfhubo respuesta? \u00bftiempo (ms)?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_gw\" data-track></textarea></label>\n                <label><span>ping 8.8.8.8 \u2014 \u00bfhubo respuesta? \u00bfconclusi\u00f3n sobre tu internet?</span><textarea rows=\"2\" data-store=\"g3r_331_ping_8888\" data-track></textarea></label>\n                <label><span>ping google.com \u2014 \u00bfhubo respuesta? compara con el anterior.</span><textarea rows=\"2\" data-store=\"g3r_331_ping_google\" data-track></textarea></label>\n                <label><span>tracert 8.8.8.8 \u2014 \u00bfcu\u00e1ntos saltos? \u00bfprimer salto y su IP?</span><textarea rows=\"2\" data-store=\"g3r_331_tracert\" data-track></textarea></label>\n                <label><span>nslookup google.com \u2014 \u00bfqu\u00e9 IP devolvi\u00f3? \u00bfqu\u00e9 servidor DNS respondi\u00f3?</span><textarea rows=\"2\" data-store=\"g3r_331_nslookup\" data-track></textarea></label>\n                <label><span>netstat -n \u2014 identifica 2 conexiones activas (IP remota y puerto).</span><textarea rows=\"2\" data-store=\"g3r_331_netstat\" data-track></textarea></label>\n                <div id=\"comandos331DeadlineControls\" style=\"margin-top:16px\"></div>\n                <div class=\"act-btn-group\">\n                  <button type=\"button\" id=\"btnGuardarComandos331\" class=\"btn-save-response\" onclick=\"actStd_save_comandos331()\">&#128190; Guardar respuestas</button>\n                  <button type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_comandos331()\">&#128196; Exportar a Word</button>\n                </div>\n                <div id=\"statusComandos331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\">&#9989; Respuestas guardadas correctamente.</div>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"activity open mission-card\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.3.2</span><span class=\"activity-title\">Procedimiento de diagn\u00f3stico de aver\u00edas \u2014 presentaci\u00f3n t\u00e9cnica</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Un t\u00e9cnico profesional no prueba comandos al azar: sigue un m\u00e9todo.\n              Elabora una presentaci\u00f3n (PowerPoint, Canva o Google Slides, <strong>m\u00ednimo 15 diapositivas</strong>) aplicando el procedimiento estructurado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#128221; Procedimiento de resoluci\u00f3n de aver\u00edas</div>\n                <p>1) Identificar el problema \u00b7 2) Establecer teor\u00eda de causa probable \u00b7 3) Comprobar la teor\u00eda \u00b7\n                4) Establecer plan de acci\u00f3n \u00b7 5) Implementar la soluci\u00f3n (o escalar) \u00b7 6) Verificar el funcionamiento completo \u00b7 7) Documentar.</p>\n              </div>\n              <div class=\"table-scroll\">\n                <table class=\"data-table\">\n                  <thead><tr><th>#</th><th>Escenario de falla</th><th>Contexto en MiPyme</th></tr></thead>\n                  <tbody>\n                    <tr><td>1</td><td>Indicadores luminosos</td><td>El switch tiene un puerto con luz \u00e1mbar en vez de verde. \u00bfQu\u00e9 indica cada color?</td></tr>\n                    <tr><td>2</td><td>Errores de hardware/software</td><td>Un PC no aparece en la red aunque el cable est\u00e1 conectado. Secuencia ping 127.0.0.1 &rarr; gateway.</td></tr>\n                    <tr><td>3</td><td>Problemas de cableado</td><td>Dos PC se ven en LAN pero sin internet. \u00bfCable, switch o router?</td></tr>\n                    <tr><td>4</td><td>Conexiones inal\u00e1mbricas</td><td>Wi-Fi conectado pero no abre p\u00e1ginas. Distinguir falla de DNS vs. internet.</td></tr>\n                    <tr><td>5</td><td>Servicios de red</td><td>DHCP no asigna IPs y todos muestran 169.254.x.x. \u00bfQu\u00e9 significa? \u00bfSoluci\u00f3n temporal?</td></tr>\n                  </tbody>\n                </table>\n              </div>\n              <p class=\"intro-text\" style=\"font-size:.86rem\">Para cada escenario indica: s\u00edntoma observable, causa probable, comandos a usar, c\u00f3mo interpretas el resultado y acci\u00f3n correctiva.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>PresentacionAverias_NombreAprendiz_FICHA</code></p></div>\n              <div data-act-std-delivery=\"presentacion332\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3.4 TRANSFERENCIA \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"transferencia\" class=\"section-title\">3.4 Transferencia del Conocimiento</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8eaf6\">&#128640;</div>\n            <div><h3>Laboratorio en Cisco Packet Tracer</h3><p>Red de edificio de dos plantas \u00b7 configurar y comprobar conectividad</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128421; Escenario \u2014 OccidenteServicios Ltda., Puerto Boyac&aacute;</h3>\n            <p>Edificio de 2 pisos. <strong>Planta 1</strong>: &aacute;rea de administraci&oacute;n \u2014 red <code>192.168.1.0/24</code>,\n            Switch S1 y <strong>4 PCs</strong> (contabilidad, gerencia, recepci&oacute;n y soporte). <strong>Planta 2</strong>:\n            &aacute;rea de operaciones \u2014 red <code>192.168.2.0/24</code>, Switch S2 y <strong>4 PCs</strong> (bodega, despacho,\n            calidad y sistemas). Un router R1 interconecta ambas plantas.\n            <strong>El objetivo no es solo configurar: es comprobar que la red funciona</strong> usando las herramientas de\n            diagn&oacute;stico. Herramientas: 2 &times; Switch 2960 (12 puertos), Router 4321.</p>\n          </article>\n\n          <div class=\"table-scroll\" style=\"margin-top:14px\">\n            <table class=\"data-table\">\n              <thead><tr><th>Dispositivo</th><th>Interfaz</th><th>Direcci&oacute;n IP</th><th>M&aacute;scara</th><th>Gateway</th><th>&Aacute;rea</th></tr></thead>\n              <tbody>\n                <tr><td><strong>R1</strong></td><td>Gi0/0/0</td><td>192.168.1.1</td><td>255.255.255.0</td><td>\u2014</td><td>Router \u2014 enlace Planta 1</td></tr>\n                <tr><td><strong>R1</strong></td><td>Gi0/0/1</td><td>192.168.2.1</td><td>255.255.255.0</td><td>\u2014</td><td>Router \u2014 enlace Planta 2</td></tr>\n                <tr><td><strong>S1</strong></td><td>VLAN 1</td><td>192.168.1.2</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Switch Planta 1</td></tr>\n                <tr><td><strong>S2</strong></td><td>VLAN 1</td><td>192.168.2.2</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Switch Planta 2</td></tr>\n                <tr><td>PC0 \u2014 Contabilidad</td><td>Fa0</td><td>192.168.1.10</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC1 \u2014 Gerencia</td><td>Fa0</td><td>192.168.1.11</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC2 \u2014 Recepci&oacute;n</td><td>Fa0</td><td>192.168.1.12</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC3 \u2014 Soporte</td><td>Fa0</td><td>192.168.1.13</td><td>255.255.255.0</td><td>192.168.1.1</td><td>Planta 1</td></tr>\n                <tr><td>PC4 \u2014 Bodega</td><td>Fa0</td><td>192.168.2.10</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC5 \u2014 Despacho</td><td>Fa0</td><td>192.168.2.11</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC6 \u2014 Calidad</td><td>Fa0</td><td>192.168.2.12</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n                <tr><td>PC7 \u2014 Sistemas</td><td>Fa0</td><td>192.168.2.13</td><td>255.255.255.0</td><td>192.168.2.1</td><td>Planta 2</td></tr>\n              </tbody>\n            </table>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:14px\">\n            <div class=\"label\">&#9881; Parte 1 \u2014 Configuraci&oacute;n b&aacute;sica (requisito para las pruebas)</div>\n            <p style=\"font-size:.83rem;margin:6px 0 10px;color:#555\">Sigue cada paso en orden. No avances al siguiente hasta confirmar que el actual funciona.</p>\n            <ol style=\"margin:0;padding-left:1.3rem;display:flex;flex-direction:column;gap:10px;font-size:.88rem\">\n              <li>\n                <strong>&#128268; Construye la topolog&iacute;a en Packet Tracer</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Agrega: Router 4321 (R1), Switch 2960 (S1), Switch 2960 (S2), 4 PCs en Planta 1, 4 PCs en Planta 2.</li>\n                  <li>Conecta cada PC a su switch con <strong>cable recto</strong>.</li>\n                  <li>Conecta S1 \u2192 R1 <code>Gi0/0/0</code> y S2 \u2192 R1 <code>Gi0/0/1</code> con <strong>cable Gigabit recto</strong>.</li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#9998; Aplica configuraci&oacute;n b&aacute;sica en R1, S1 y S2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Hostname: <code>R1-XXX</code> / <code>S1-XXX</code> / <code>S2-XXX</code> (XXX = \u00faltimos 3 d\u00edgitos de tu identidad).</li>\n                  <li>Banner de bienvenida (<code>banner motd</code>), <code>enable secret</code>, contrase\u00f1as de consola y VTY.</li>\n                  <li><code>service password-encryption</code>, <code>no ip domain-lookup</code>, <code>logging synchronous</code>.</li>\n                  <li>Guarda con <code>write memory</code> en cada dispositivo. <em>(Ver c\u00e1psula &#128204; si no recuerdas los comandos.)</em></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#127760; Configura las interfaces del router R1</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li><code>Gi0/0/0</code> \u2192 192.168.1.1 /24 (<code>no shutdown</code>) \u2014 gateway Planta 1.</li>\n                  <li><code>Gi0/0/1</code> \u2192 192.168.2.1 /24 (<code>no shutdown</code>) \u2014 gateway Planta 2.</li>\n                  <li>Verifica: <code>show ip interface brief</code> \u2014 ambas deben aparecer <strong>up/up</strong>. <em>(Ver c\u00e1psula &#128204;.)</em></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#128256; Configura la IP de administraci&oacute;n VLAN 1 en S1 y S2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>S1: <code>interface vlan 1</code> \u2192 192.168.1.2 /24 + <code>ip default-gateway 192.168.1.1</code></li>\n                  <li>S2: <code>interface vlan 1</code> \u2192 192.168.2.2 /24 + <code>ip default-gateway 192.168.2.1</code></li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#128187; Asigna IPs est&aacute;ticas a los 8 PCs</strong> (seg&uacute;n tabla de direccionamiento de arriba)\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Planta 1 \u2014 PC0\u2013PC3: 192.168.1.10\u2013.13 | Gateway: 192.168.1.1</li>\n                  <li>Planta 2 \u2014 PC4\u2013PC7: 192.168.2.10\u2013.13 | Gateway: 192.168.2.1</li>\n                </ul>\n              </li>\n              <li>\n                <strong>&#9989; Verificaci&oacute;n m&iacute;nima antes de pasar a la Parte 2</strong>\n                <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                  <li>Desde PC0: <code>ping 192.168.1.1</code> \u2192 debe responder (gateway Planta 1).</li>\n                  <li>Desde PC4: <code>ping 192.168.2.1</code> \u2192 debe responder (gateway Planta 2).</li>\n                  <li>Si falla, revisa <code>no shutdown</code> en las interfaces y que la IP del PC tenga el gateway correcto.</li>\n                </ul>\n              </li>\n            </ol>\n          </div>\n\n          <!-- C\u00e1psulas de recordatorio 3.4.1 -->\n          <div style=\"display:flex;flex-direction:column;gap:8px;margin:14px 0\">\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 C&oacute;mo configurar hostname, banner y contrase&ntilde;as en un router o switch\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">enable\nconfigure terminal\nhostname R1-XXX\nbanner motd # Acceso restringido \u2014 solo personal autorizado #\nenable secret cisco123\nline console 0\n password cisco\n login\n logging synchronous\nline vty 0 4\n password cisco\n login\nservice password-encryption\nno ip domain-lookup\nend\nwrite memory</pre>\n              </div>\n            </details>\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 C&oacute;mo configurar las interfaces del router (R1) e IP de VLAN en el switch\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <p style=\"font-size:.82rem;margin:0 0 8px;font-weight:600\">Router R1 \u2014 interfaces hacia cada planta:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">interface GigabitEthernet0/0/0\n ip address 192.168.1.1 255.255.255.0\n no shutdown\ninterface GigabitEthernet0/0/1\n ip address 192.168.2.1 255.255.255.0\n no shutdown</pre>\n                <p style=\"font-size:.82rem;margin:10px 0 8px;font-weight:600\">Switch S1 \u2014 IP de administraci&oacute;n VLAN 1:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">interface vlan 1\n ip address 192.168.1.2 255.255.255.0\n no shutdown\nip default-gateway 192.168.1.1</pre>\n              </div>\n            </details>\n\n            <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n              <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                Recordatorio \u2014 Comandos de verificaci&oacute;n m&aacute;s usados\n              </summary>\n              <div style=\"padding:12px 16px;background:#fafafa\">\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">show ip interface brief        ! estado up/up de cada interfaz\nshow running-config            ! ver toda la configuraci\u00f3n actual\nshow ip route                  ! tabla de enrutamiento del router\nping 192.168.1.1               ! prueba de conectividad b\u00e1sica\ntracert 192.168.2.10           ! ruta de saltos (desde PC en CMD)\ntelnet 192.168.1.1             ! acceso remoto al router</pre>\n              </div>\n            </details>\n\n          </div>\n\n          <div class=\"info-box green\" style=\"margin-top:14px\"><div class=\"label\">&#9989; Parte 2 \u2014 Comprobaci&oacute;n de conectividad (captura cada prueba)</div></div>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>#</th><th>Prueba</th><th>&iquest;Qu&eacute; confirma?</th></tr></thead>\n              <tbody>\n                <tr><td>1</td><td>PC0: <code>ping 192.168.1.1</code></td><td>LAN Planta 1 \u2014 PC0 alcanza el router</td></tr>\n                <tr><td>2</td><td>PC2: <code>ping 192.168.1.13</code></td><td>Comunicaci&oacute;n entre todos los PCs de Planta 1</td></tr>\n                <tr><td>3</td><td>PC4: <code>ping 192.168.2.1</code></td><td>LAN Planta 2 \u2014 PC4 alcanza el router</td></tr>\n                <tr><td>4</td><td>PC6: <code>ping 192.168.2.13</code></td><td>Comunicaci&oacute;n entre todos los PCs de Planta 2</td></tr>\n                <tr><td>5</td><td>PC0: <code>ping 192.168.2.10</code></td><td>Enrutamiento entre plantas (Planta 1 \u2192 Planta 2)</td></tr>\n                <tr><td>6</td><td>PC7: <code>ping 192.168.1.11</code></td><td>Enrutamiento inverso (Planta 2 \u2192 Planta 1)</td></tr>\n                <tr><td>7</td><td>PC3: <code>ping 192.168.1.2</code> (S1)</td><td>Gesti&oacute;n del switch S1 accesible</td></tr>\n                <tr><td>8</td><td>PC5: <code>ping 192.168.2.2</code> (S2)</td><td>Gesti&oacute;n del switch S2 accesible</td></tr>\n                <tr><td>9</td><td>PC0: <code>tracert 192.168.2.13</code></td><td>Ruta de enrutamiento entre plantas (2 saltos)</td></tr>\n                <tr><td>10</td><td>PC4: <code>telnet 192.168.1.1</code></td><td>Acceso administrativo remoto al router desde Planta 2</td></tr>\n              </tbody>\n            </table>\n          </div>\n\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.4.1</span><span class=\"activity-title\">Entrega del laboratorio (.pkt + PDF con 10 pruebas)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Criterio clave:</strong> no basta con capturar las pruebas\n              &mdash; explica brevemente qu\u00e9 confirma cada una y qu\u00e9 habr\u00eda significado si hubiera fallado.</p>\n              <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div><p><code>Lab_Conectividad_NombreAprendiz_FICHA.pkt</code> + PDF con las 10 capturas comentadas.</p></div>\n              <div data-act-std-delivery=\"laboratorio341\"></div>\n            </div>\n          </div>\n          <!-- Actividad 3.4.2 -->\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3.4.2</span>\n              <span class=\"activity-title\">Laboratorio integral \u2014 Red con DHCP, DNS, AP y NAT (Packet Tracer)</span>\n              <span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n\n              <article class=\"story-card\">\n                <h3>&#127981; Escenario \u2014 Cooperativa Agropecuaria Los Andes, Duitama</h3>\n                <p>La cooperativa tiene una sola planta con <strong>oficinas administrativas</strong> (5 PCs con IP fija) y\n                una <strong>sala de atenci&oacute;n al p&uacute;blico</strong> con Wi-Fi (3 laptops de visitantes por DHCP).\n                Adem&aacute;s requieren un servidor DNS interno, salida a internet mediante NAT y que el t&eacute;cnico\n                pueda administrar el router y el switch de forma remota. T&uacute; eres el t&eacute;cnico encargado\n                de construir y verificar toda esta red en Cisco Packet Tracer.</p>\n              </article>\n\n              <div class=\"table-scroll\" style=\"margin-top:14px\">\n                <table class=\"data-table\">\n                  <thead><tr><th>Dispositivo</th><th>Interfaz</th><th>Direcci&oacute;n IP</th><th>M&aacute;scara</th><th>Gateway</th><th>Rol</th></tr></thead>\n                  <tbody>\n                    <tr><td><strong>R1</strong></td><td>Gi0/0/0 (LAN)</td><td>192.168.20.1</td><td>255.255.255.0</td><td>\u2014</td><td>Gateway + DHCP + NAT</td></tr>\n                    <tr><td><strong>R1</strong></td><td>Gi0/0/1 (WAN)</td><td>200.15.10.1</td><td>255.255.255.252</td><td>\u2014</td><td>Salida a internet (IP p&uacute;blica)</td></tr>\n                    <tr><td><strong>ISP</strong></td><td>Gi0/0/0</td><td>200.15.10.2</td><td>255.255.255.252</td><td>\u2014</td><td>Simula el ISP</td></tr>\n                    <tr><td><strong>S1</strong></td><td>VLAN 1</td><td>192.168.20.2</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Switch de acceso (administrable)</td></tr>\n                    <tr><td><strong>DNS-Server</strong></td><td>Fa0</td><td>192.168.20.3</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Servidor DNS interno</td></tr>\n                    <tr><td>PC-Gerencia</td><td>Fa0</td><td>192.168.20.10</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Contabilidad</td><td>Fa0</td><td>192.168.20.11</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Sistemas</td><td>Fa0</td><td>192.168.20.12</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Recepci&oacute;n</td><td>Fa0</td><td>192.168.20.13</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td>PC-Almac&eacute;n</td><td>Fa0</td><td>192.168.20.14</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Oficina \u2014 IP fija</td></tr>\n                    <tr><td><strong>AP-Sala</strong></td><td>\u2014</td><td>192.168.20.5</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Access Point (SSID: CoopAndes)</td></tr>\n                    <tr><td>Laptop-Visita1</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                    <tr><td>Laptop-Visita2</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                    <tr><td>Laptop-Visita3</td><td>Wi-Fi</td><td>DHCP (.100\u2013.150)</td><td>255.255.255.0</td><td>192.168.20.1</td><td>Visitante Wi-Fi</td></tr>\n                  </tbody>\n                </table>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:14px\">\n                <div class=\"label\">&#9881; Parte 1 \u2014 Construir la topolog&iacute;a y configuraci&oacute;n base</div>\n                <p style=\"font-size:.83rem;margin:6px 0 10px;color:#555\">Sigue cada paso en orden. No avances al siguiente hasta confirmar que el actual funciona.</p>\n                <ol style=\"margin:0;padding-left:1.3rem;display:flex;flex-direction:column;gap:10px;font-size:.88rem\">\n                  <li>\n                    <strong>&#128268; Construye la topolog&iacute;a en Packet Tracer</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>Dispositivos: Router 4321 (R1), Router gen\u00e9rico (ISP), Switch 2960 (S1), Access Point WRT300N (AP-Sala), 5 PCs, 1 Server, 3 Laptops.</li>\n                      <li>Conecta PCs, Server y AP \u2192 S1 con <strong>cable recto</strong>.</li>\n                      <li>Conecta S1 \u2192 R1 <code>Gi0/0/0</code> con <strong>cable recto Gigabit</strong>.</li>\n                      <li>Conecta R1 <code>Gi0/0/1</code> \u2192 ISP con <strong>cable cruzado</strong> (o Serial si el modelo lo exige).</li>\n                      <li>Las 3 Laptops se conectan <strong>por Wi-Fi</strong> al AP (SSID: <code>CoopAndes</code>). <em>(Ver c\u00e1psula &#128204; AP.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#9998; Aplica configuraci&oacute;n b&aacute;sica en R1 y S1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>Hostname: <code>R1-CoopAndes</code> / <code>S1-CoopAndes</code>.</li>\n                      <li>Banner de bienvenida, <code>enable secret</code>, contrase\u00f1as de consola y VTY.</li>\n                      <li><code>service password-encryption</code>, <code>no ip domain-lookup</code>, <code>logging synchronous</code>.</li>\n                      <li>Guarda con <code>write memory</code>. <em>(Ver c\u00e1psula &#128204; hostname/contrase\u00f1as.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#127760; Configura las interfaces de R1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li><code>Gi0/0/0</code> (LAN) \u2192 192.168.20.1 /24 + <code>no shutdown</code>.</li>\n                      <li><code>Gi0/0/1</code> (WAN) \u2192 200.15.10.1 /30 + <code>no shutdown</code>.</li>\n                      <li>ISP: <code>Gi0/0/0</code> \u2192 200.15.10.2 /30 + <code>no shutdown</code>.</li>\n                      <li>Verifica: <code>show ip interface brief</code> \u2014 todas <strong>up/up</strong>.</li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#128256; Configura VLAN 1 de administraci&oacute;n en S1</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li><code>interface vlan 1</code> \u2192 192.168.20.2 /24 + <code>no shutdown</code>.</li>\n                      <li><code>ip default-gateway 192.168.20.1</code></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#128187; Asigna IPs est&aacute;ticas a los 5 PCs de oficina y al Servidor DNS</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>PC-Gerencia .10 \u00b7 PC-Contabilidad .11 \u00b7 PC-Sistemas .12 \u00b7 PC-Recepci\u00f3n .13 \u00b7 PC-Almac\u00e9n .14 \u2014 todas con gateway 192.168.20.1</li>\n                      <li>DNS-Server: 192.168.20.3 /24 | Gateway: 192.168.20.1 | DNS: 192.168.20.3</li>\n                      <li>AP-Sala: 192.168.20.5 /24 | Gateway: 192.168.20.1 <em>(ver c\u00e1psula &#128204; AP.)</em></li>\n                    </ul>\n                  </li>\n                  <li>\n                    <strong>&#9989; Verificaci&oacute;n m&iacute;nima antes de pasar a la Parte 2</strong>\n                    <ul style=\"margin:4px 0 0 1rem;padding:0;list-style:disc;color:#444;font-size:.85rem;display:flex;flex-direction:column;gap:3px\">\n                      <li>PC-Gerencia: <code>ping 192.168.20.1</code> \u2192 debe responder.</li>\n                      <li>PC-Gerencia: <code>ping 200.15.10.2</code> (ISP WAN) \u2192 debe responder.</li>\n                      <li>Si falla, revisa <code>no shutdown</code> en <code>Gi0/0/0</code> y la IP del PC.</li>\n                    </ul>\n                  </li>\n                </ol>\n              </div>\n\n              <!-- C\u00e1psulas de recordatorio 3.4.2 -->\n              <div style=\"display:flex;flex-direction:column;gap:8px;margin:14px 0\">\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar hostname, banner y contrase&ntilde;as en R1\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">enable\nconfigure terminal\nhostname R1-CoopAndes\nbanner motd # Acceso restringido \u2014 Cooperativa Los Andes #\nenable secret cisco123\nline console 0\n password cisco\n login\n logging synchronous\nline vty 0 4\n password cisco\n login\nservice password-encryption\nno ip domain-lookup\nend\nwrite memory</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar DHCP en el router (Bloque C)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">ip dhcp excluded-address 192.168.20.1 192.168.20.99\nip dhcp pool VISITANTES\n network 192.168.20.0 255.255.255.0\n default-router 192.168.20.1\n dns-server 192.168.20.3\n!\n! Verificar asignaciones:\nshow ip dhcp binding\nshow ip dhcp pool</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar NAT overload (PAT) en el router (Bloque D)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.8rem;overflow-x:auto;margin:0\">! 1. Definir qu\u00e9 IPs se van a traducir\naccess-list 1 permit 192.168.20.0 0.0.0.255\n!\n! 2. Aplicar NAT overload usando la interfaz WAN\nip nat inside source list 1 interface GigabitEthernet0/0/1 overload\n!\n! 3. Marcar las interfaces\ninterface GigabitEthernet0/0/0\n ip nat inside\ninterface GigabitEthernet0/0/1\n ip nat outside\n!\n! Verificar:\nshow ip nat translations\nshow ip nat statistics</pre>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar el servidor DNS en Packet Tracer (Bloque C)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <ol style=\"font-size:.85rem;line-height:1.9;margin:0;padding-left:18px\">\n                      <li>Haz clic en el <strong>DNS-Server</strong> \u2192 pesta&ntilde;a <strong>Services</strong> \u2192 <strong>DNS</strong></li>\n                      <li>Activa el servicio: <strong>DNS Service \u2192 ON</strong></li>\n                      <li>Agrega el primer registro: Name <code>cooperativa.local</code> \u2192 Type <code>A Record</code> \u2192 Address <code>192.168.20.10</code> \u2192 <strong>Add</strong></li>\n                      <li>Agrega el segundo: Name <code>intranet.local</code> \u2192 Type <code>A Record</code> \u2192 Address <code>192.168.20.11</code> \u2192 <strong>Add</strong></li>\n                      <li>Verifica desde PC-Gerencia con <code>nslookup cooperativa.local</code> en el Command Prompt</li>\n                    </ol>\n                  </div>\n                </details>\n\n                <details style=\"border:1.5px solid #b0bec5;border-radius:10px;overflow:hidden\">\n                  <summary style=\"padding:10px 14px;background:#eceff1;cursor:pointer;font-weight:700;font-size:.88rem;list-style:none;display:flex;align-items:center;gap:8px\">\n                    <span style=\"background:#455a64;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem;flex-shrink:0\">&#128204;</span>\n                    Recordatorio \u2014 C&oacute;mo configurar el Access Point y conectar laptops por Wi-Fi (Bloque A)\n                  </summary>\n                  <div style=\"padding:12px 16px;background:#fafafa\">\n                    <ol style=\"font-size:.85rem;line-height:1.9;margin:0;padding-left:18px\">\n                      <li>Haz clic en el <strong>AP-Sala</strong> \u2192 pesta&ntilde;a <strong>Config</strong> \u2192 <strong>Port 1 (Wireless)</strong></li>\n                      <li>SSID: <code>CoopAndes</code> \u2014 Authentication: <strong>WPA2-PSK</strong> \u2014 PSK Pass Phrase: <code>coop2025</code></li>\n                      <li>Asigna IP fija al AP: <code>192.168.20.5</code>, m&aacute;scara <code>255.255.255.0</code>, gateway <code>192.168.20.1</code></li>\n                      <li>En cada <strong>Laptop</strong>: retira la tarjeta de red cableada (si tiene) e instala la tarjeta <strong>WPC300N</strong></li>\n                      <li>Laptop \u2192 pesta&ntilde;a <strong>Desktop</strong> \u2192 <strong>PC Wireless</strong> \u2192 Connect \u2192 selecciona <code>CoopAndes</code> \u2192 ingresa la clave</li>\n                      <li>Verifica con <code>ipconfig</code> que recibi&oacute; IP en el rango <code>192.168.20.100\u2013150</code></li>\n                    </ol>\n                  </div>\n                </details>\n\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127968; Parte 2 \u2014 DHCP en el router (Bloque C)</div>\n                <p style=\"font-size:.88rem\">Configura un pool DHCP en R1 para los dispositivos inal&aacute;mbricos:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.82rem;overflow-x:auto;margin-top:8px\">ip dhcp pool VISITANTES\n network 192.168.20.0 255.255.255.0\n default-router 192.168.20.1\n dns-server 192.168.20.3\nip dhcp excluded-address 192.168.20.1 192.168.20.99</pre>\n                <p style=\"font-size:.85rem;margin-top:6px\">Verifica con <code>show ip dhcp binding</code> que la Laptop recibi&oacute; IP del rango .100\u2013.150.</p>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127758; Parte 3 \u2014 DNS interno (Bloque C)</div>\n                <p style=\"font-size:.88rem\">En el <strong>DNS-Server</strong> (192.168.20.3), activa el servicio DNS y agrega los registros:</p>\n                <div class=\"table-scroll\" style=\"margin-top:8px\">\n                  <table class=\"data-table\">\n                    <thead><tr><th>Nombre</th><th>Tipo</th><th>IP</th></tr></thead>\n                    <tbody>\n                      <tr><td><code>cooperativa.local</code></td><td>A Record</td><td>192.168.20.10</td></tr>\n                      <tr><td><code>intranet.local</code></td><td>A Record</td><td>192.168.20.11</td></tr>\n                    </tbody>\n                  </table>\n                </div>\n                <p style=\"font-size:.85rem;margin-top:8px\">Verifica desde PC-Admin1 con el comando <code>nslookup cooperativa.local</code> \u2014 debe devolver <code>192.168.20.10</code>.</p>\n              </div>\n\n              <div class=\"info-box\" style=\"margin-top:10px\">\n                <div class=\"label\">&#127757; Parte 4 \u2014 NAT overload (PAT) hacia internet (Bloque D)</div>\n                <p style=\"font-size:.88rem\">Configura NAT en R1 para que toda la LAN salga con la IP p&uacute;blica <code>200.15.10.1</code>:</p>\n                <pre style=\"background:#1a237e;color:#e8eaf6;border-radius:8px;padding:12px;font-size:.82rem;overflow-x:auto;margin-top:8px\">access-list 1 permit 192.168.20.0 0.0.0.255\nip nat inside source list 1 interface Gi0/0/1 overload\ninterface Gi0/0/0\n ip nat inside\ninterface Gi0/0/1\n ip nat outside</pre>\n                <p style=\"font-size:.85rem;margin-top:6px\">Verifica con <code>show ip nat translations</code> despu&eacute;s de hacer ping al ISP desde un PC.</p>\n              </div>\n\n              <div class=\"info-box green\" style=\"margin-top:14px\">\n                <div class=\"label\">&#9989; Parte 5 \u2014 Pruebas de conectividad (captura cada una)</div>\n              </div>\n              <div class=\"table-scroll\">\n                <table class=\"data-table\">\n                  <thead><tr><th>#</th><th>Prueba</th><th>&iquest;Qu&eacute; confirma?</th></tr></thead>\n                  <tbody>\n                    <tr><td>1</td><td>PC-Gerencia: <code>ping 192.168.20.1</code></td><td>LAN OK \u2014 PC de oficina alcanza el gateway</td></tr>\n                    <tr><td>2</td><td>PC-Gerencia: <code>ping 192.168.20.14</code></td><td>Comunicaci&oacute;n entre los 5 PCs de oficina</td></tr>\n                    <tr><td>3</td><td>PC-Sistemas: <code>ping 192.168.20.3</code></td><td>Servidor DNS interno alcanzable</td></tr>\n                    <tr><td>4</td><td>PC-Gerencia: <code>nslookup cooperativa.local</code></td><td>DNS interno resuelve el nombre \u2192 192.168.20.10 (Bloque C)</td></tr>\n                    <tr><td>5</td><td>Laptop-Visita1: <code>ipconfig</code></td><td>DHCP asign&oacute; IP en rango .100\u2013.150 (Bloque C)</td></tr>\n                    <tr><td>6</td><td>Laptop-Visita2: <code>ipconfig</code></td><td>Segunda laptop Wi-Fi tambi&eacute;n obtuvo IP por DHCP</td></tr>\n                    <tr><td>7</td><td>Laptop-Visita1: <code>ping 192.168.20.12</code></td><td>Visitante Wi-Fi se comunica con red cableada (AP OK \u2014 Bloque A)</td></tr>\n                    <tr><td>8</td><td>PC-Recepci&oacute;n: <code>ping 200.15.10.2</code></td><td>Salida WAN \u2014 NAT traduce IP privada a p&uacute;blica (Bloque D)</td></tr>\n                    <tr><td>9</td><td>PC-Almac&eacute;n: <code>tracert 200.15.10.2</code></td><td>Ruta de salida a internet verificada (Bloque B)</td></tr>\n                    <tr><td>10</td><td>R1: <code>show ip nat translations</code></td><td>Tabla NAT muestra todas las traducciones activas (Bloque D)</td></tr>\n                  </tbody>\n                </table>\n              </div>\n\n              <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n                <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n                  <span class=\"activity-num\">3.4.2</span>\n                  <span class=\"activity-title\">Entrega del laboratorio integral (.pkt + PDF con 10 pruebas)</span>\n                  <span class=\"activity-toggle\">&#9662;</span>\n                </div>\n                <div class=\"activity-body\">\n                  <p class=\"intro-text\" style=\"margin-top:0\"><strong>Criterio clave:</strong> en el PDF comenta cada captura\n                  explicando qu&eacute; servicio o concepto (DHCP, DNS, NAT, AP, TCP/IP) confirma esa prueba y\n                  qu&eacute; habr&iacute;a significado si hubiera fallado.</p>\n                  <div class=\"info-box green\"><div class=\"label\">&#128206; Nombre del archivo</div>\n                    <p><code>LabIntegral_NombreAprendiz_FICHA.pkt</code> + PDF con las 10 capturas comentadas.</p>\n                  </div>\n                  <div data-act-std-delivery=\"caso342\"></div>\n                </div>\n              </div>\n\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 QUIZ \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"quiz\" class=\"section-title\">Quiz de conectividad</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff8e1\">&#10067;</div>\n            <div><h3>Autoevaluaci\u00f3n: comprobar conectividad</h3><p>Verifica tu comprensi\u00f3n de dispositivos, servicios y comandos</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">Pon a prueba lo aprendido sobre dispositivos activos, TCP/IP,\n          DHCP/DNS/Firewall, NAT y comandos de diagn\u00f3stico. El quiz registra tu intento.</p>\n          <a class=\"btn-save-response\" id=\"quizRedesActionLink\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"display:inline-flex;align-items:center;gap:8px;text-decoration:none\">&#10067; Abrir el quiz de conectividad</a>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 EVIDENCIAS \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"evidencias\" class=\"section-title\">Evidencias de Aprendizaje</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#e1f5fe\">&#128202;</div><div><h3>Productos y criterios de evaluaci\u00f3n</h3><p>Lo que se eval\u00faa en cada actividad</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Actividad</th><th>Evidencia / Producto</th><th>Instrumento</th></tr></thead>\n              <tbody>\n                <tr><td>3.2 Contextualizaci\u00f3n (Bloques A\u2013D)</td><td>PDF con diagrama de red, tabla TCP/IP, an\u00e1lisis DHCP/DNS/Firewall y esquema NAT.</td><td>Lista de chequeo IE-01</td></tr>\n                <tr><td>3.3.1 / 3.3.2 Apropiaci\u00f3n</td><td>Portafolio de comandos CLI + presentaci\u00f3n t\u00e9cnica de aver\u00edas.</td><td>Lista de chequeo IE-02</td></tr>\n                <tr><td>3.4 Transferencia</td><td>Archivo .pkt + PDF con 10 pruebas de conectividad comentadas.</td><td>Lista de chequeo IE-03</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 GLOSARIO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"glosario\" class=\"section-title\">Glosario de t\u00e9rminos</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#f3e5f5\">&#128214;</div><div><h3>Glosario</h3><p>T\u00e9rminos clave de la gu\u00eda</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <dl class=\"glossary\">\n            <dt>Router</dt><dd>Interconecta dos o m\u00e1s redes y reenv\u00eda paquetes IP; en MiPymes act\u00faa como puerta de enlace y puede hacer NAT.</dd>\n            <dt>Switch</dt><dd>Dispositivo de capa 2 que conmuta tramas Ethernet entre puertos dentro de una LAN.</dd>\n            <dt>Access Point (AP)</dt><dd>Brinda acceso inal\u00e1mbrico (Wi-Fi) a una red cableada.</dd>\n            <dt>TCP/IP</dt><dd>Conjunto de protocolos base de Internet organizado por capas; IP direcciona y encamina, TCP/UDP transportan datos.</dd>\n            <dt>DHCP</dt><dd>Asigna autom\u00e1ticamente IP, m\u00e1scara, gateway y DNS a los equipos cliente.</dd>\n            <dt>DNS</dt><dd>Traduce nombres de dominio (p. ej. www.google.com) a direcciones IP.</dd>\n            <dt>NAT</dt><dd>Traduce direcciones IP privadas a una o varias p\u00fablicas para salir a Internet desde una LAN.</dd>\n            <dt>ICMP</dt><dd>Protocolo de control y diagn\u00f3stico; el comando ping lo usa para verificar conectividad.</dd>\n            <dt>Gateway (Puerta de enlace)</dt><dd>IP del router por donde un equipo env\u00eda el tr\u00e1fico hacia otras redes.</dd>\n            <dt>M\u00e1scara de subred</dt><dd>Define qu\u00e9 parte de la IP es red y qu\u00e9 parte es host.</dd>\n            <dt>APIPA (169.254.x.x)</dt><dd>IP link-local autom\u00e1tica cuando el equipo no obtiene configuraci\u00f3n v\u00e1lida de DHCP.</dd>\n            <dt>VLAN</dt><dd>Segmentaci\u00f3n l\u00f3gica de una LAN en dominios de broadcast independientes.</dd>\n            <dt>tracert / traceroute</dt><dd>Muestra la ruta (saltos) hasta un destino; \u00fatil para ubicar d\u00f3nde se pierde la conexi\u00f3n.</dd>\n            <dt>nslookup</dt><dd>Consulta servidores DNS para verificar la resoluci\u00f3n de nombres.</dd>\n            <dt>netstat</dt><dd>Muestra conexiones de red activas, puertos en escucha y estad\u00edsticas.</dd>\n            <dt>Cisco Packet Tracer</dt><dd>Simulador de redes para construir topolog\u00edas, configurar dispositivos y validar conectividad.</dd>\n            <dt>Telnet</dt><dd>Acceso remoto por texto plano (sin cifrado); \u00fatil en laboratorio, no recomendado en producci\u00f3n.</dd>\n            <dt>Firewall</dt><dd>Filtra el tr\u00e1fico de red seg\u00fan reglas para permitir o bloquear comunicaciones.</dd>\n          </dl>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 REFERENCIAS \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"referencias\" class=\"section-title\">Referentes bibliogr\u00e1ficos</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#eceff1\">&#128279;</div><div><h3>Referencias (IEEE)</h3><p>Fuentes consultadas</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <ol class=\"references\">\n            <li>Cisco Networking Academy, \u00abNetworking Basics\u00bb, Cisco Skills for All.</li>\n            <li>J. Postel, \u00abInternet Protocol\u00bb, RFC 791, 1981.</li>\n            <li>J. Postel, \u00abTransmission Control Protocol\u00bb, RFC 793, 1981.</li>\n            <li>J. Postel, \u00abUser Datagram Protocol\u00bb, RFC 768, 1980.</li>\n            <li>R. Droms, \u00abDynamic Host Configuration Protocol\u00bb, RFC 2131, 1997.</li>\n            <li>P. Mockapetris, \u00abDomain names - concepts and facilities\u00bb, RFC 1034, 1987.</li>\n            <li>T. Hain, \u00abTraditional IP Network Address Translator (NAT)\u00bb, RFC 3022, 2001.</li>\n            <li>Microsoft, \u00abipconfig / ping / tracert / nslookup / netstat\u00bb, Microsoft Learn (Windows Commands).</li>\n            <li>S. Cheshire et al., \u00abDynamic Configuration of IPv4 Link-Local Addresses\u00bb, RFC 3927, 2005.</li>\n            <li>J. Postel, \u00abInternet Control Message Protocol\u00bb, RFC 792, 1981.</li>\n            <li>Cisco, \u00abVLAN Fundamentals\u00bb y \u00abCisco Packet Tracer\u00bb, netacad.com.</li>\n            <li>K. Scarfone y P. Hoffman, \u00abGuidelines on Firewalls and Firewall Policy\u00bb, NIST SP 800-41 Rev. 1, 2009.</li>\n            <li>J. Postel y J. Reynolds, \u00abTELNET Protocol Specification\u00bb, RFC 854, 1983.</li>\n          </ol>\n          <p class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\">Gu\u00eda original: Boris Vesga Cardozo (Instructor, CIAS). Actualizaci\u00f3n al Proyecto Formativo: Dubier Orlando Mill\u00e1n Barbosa (Instructor T\u00e9cnico, CIAS \u2014 Regional Boyac\u00e1).</p>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n";
